select ac_cargar_unidad($ac${"slug":"tronco-1","rama":"tronco","orden":1,"nivel":0,"titulo_es":"Todo está conectado","bajada_es":"Las cuatro ideas que sostienen todo lo demás: qué es el ambiente, cómo circula la materia, cómo fluye la energía y por qué todo tiene efectos en cadena.","objetivos_es":["Explicar qué es el ambiente y reconocer que vos formás parte de él","Seguir el recorrido de la materia: el agua y el carbono dan vueltas y nada desaparece","Describir cómo entra la energía del sol a los seres vivos y por qué se va perdiendo","Reconocer efectos en cadena, retroalimentaciones y consecuencias no buscadas","Distinguir un recurso renovable de uno no renovable y por qué el ritmo de uso importa"],"repasa":[],"requiere_tronco":0,"fuentes":["unesco-ods","usgs-ciclo-agua","nasa-ciclo-carbono","ipbes-global","global-footprint","invasoras-mayds","unep"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"tronco-1.s1","orden":1,"tipo":"leccion","titulo_es":"¿Qué es el ambiente?","bajada_es":"No es un lugar lejano con árboles: es todo lo que te rodea, incluido vos.","minutos":11,"pasos":[{"slug":"tronco-1.s1.p1","orden":1,"grupo":"tronco-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El ambiente empieza en tu casa","cuerpo":["Cuando se dice \"ambiente\", mucha gente imagina una selva o una montaña lejos de la ciudad. Pero el ambiente es todo lo que rodea a los seres vivos y se relaciona con ellos: el aire de tu cuarto, el agua de la canilla, la plaza de tu barrio, la comida de tu heladera y también las personas.","Tiene partes vivas —plantas, animales, hongos, bacterias, personas— y partes no vivas —agua, aire, suelo, luz, temperatura—. Lo interesante no son las partes por separado sino cómo se afectan entre sí."],"destacado":{"valor":"Vos","texto":"también sos parte del ambiente: respirás su aire, tomás su agua y lo cambiás con lo que hacés."}},"solucion":{}},{"slug":"tronco-1.s1.p2","orden":2,"grupo":"tronco-1.s1.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estas opciones describe mejor qué es el ambiente?","opciones":[{"id":"o1","texto":"Todo lo que rodea a los seres vivos, incluidas las ciudades y las personas"},{"id":"o2","texto":"Solo las zonas naturales que no fueron tocadas por las personas"},{"id":"o3","texto":"Los animales, las plantas y los paisajes naturales, sin contar las ciudades"},{"id":"o4","texto":"Los parques nacionales, las reservas y las áreas protegidas del país"}]},"solucion":{"clave":["o1"],"explicacion":"El ambiente incluye lo natural y lo construido. Una ciudad también es un ambiente: tiene aire, agua, suelo, seres vivos y personas que lo transforman todos los días.","por_opcion":{"o2":"Es la idea más común, pero deja afuera justo el lugar donde vivís y donde más podés actuar."}}},{"slug":"tronco-1.s1.p3","orden":3,"grupo":"tronco-1.s1.p3","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Separá lo vivo de lo no vivo en un parque.","grupos":[{"id":"g1","nombre":"Parte viva"},{"id":"g2","nombre":"Parte no viva"}],"items":[{"id":"i1","texto":"Un árbol"},{"id":"i2","texto":"El agua del charco"},{"id":"i3","texto":"Una lombriz"},{"id":"i4","texto":"La luz del sol"},{"id":"i5","texto":"El hongo de un tronco"},{"id":"i6","texto":"Una piedra"},{"id":"i7","texto":"Una persona"},{"id":"i8","texto":"El aire"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Los componentes vivos (bióticos) crecen, se alimentan y se reproducen. Los no vivos (abióticos) no lo hacen, pero son indispensables: sin agua, luz ni aire, lo vivo no existe."}},{"slug":"tronco-1.s1.p4","orden":4,"grupo":"tronco-1.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las partes se afectan entre sí","cuerpo":["Un árbol de la vereda parece una cosa sola, pero está conectado con todo: sus raíces sostienen el suelo y absorben agua de lluvia, sus hojas dan sombra y bajan la temperatura de la cuadra, y en sus ramas comen y anidan pájaros e insectos.","Si se tala el árbol, cambian muchas cosas a la vez: la vereda se calienta más, el agua de lluvia corre en lugar de infiltrarse y los pájaros buscan otro lugar. Por eso en ambiente casi nada tiene un solo efecto."]},"solucion":{}},{"slug":"tronco-1.s1.p5","orden":5,"grupo":"tronco-1.s1.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué cambia en una cuadra si se saca su único árbol grande? Marcá todo lo que corresponde.","opciones":[{"id":"o1","texto":"La vereda y las casas reciben más sol directo y se calientan más"},{"id":"o2","texto":"Menos agua de lluvia se infiltra en el suelo en ese lugar"},{"id":"o3","texto":"Los pájaros que lo usaban pierden un lugar para comer o descansar"},{"id":"o4","texto":"El aire de toda la ciudad se queda sin oxígeno"},{"id":"o5","texto":"Deja de llover en esa cuadra"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Un árbol hace muchas cosas al mismo tiempo: sombra, infiltración, refugio. Pero tampoco hay que exagerar: un solo árbol no controla la lluvia ni el oxígeno de una ciudad. Pensar en ambiente es ver los efectos reales, sin agrandarlos ni achicarlos."}},{"slug":"tronco-1.s1.p6","orden":6,"grupo":"tronco-1.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La naturaleza trabaja gratis","cuerpo":["Muchas cosas que necesitamos las hace la naturaleza sin que nadie las pague: las abejas y otros insectos polinizan cultivos, los humedales absorben agua y amortiguan inundaciones, el suelo filtra el agua de lluvia y los bosques guardan carbono.","A estos beneficios se los llama servicios de los ecosistemas. Cuando un ecosistema se degrada, esos servicios no desaparecen de la cuenta: hay que reemplazarlos con obras, dinero o energía, y a veces no se pueden reemplazar."],"lista":["Polinización de frutas y verduras","Agua filtrada por suelos y humedales","Sombra y frescura de los árboles","Suelo fértil formado por hongos, lombrices y bacterias"]},"solucion":{}},{"slug":"tronco-1.s1.p7","orden":7,"grupo":"tronco-1.s1.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte de la naturaleza con el servicio que nos da.","izquierda":[{"id":"a1","texto":"Insectos polinizadores"},{"id":"a2","texto":"Humedal"},{"id":"a3","texto":"Árboles en la ciudad"},{"id":"a4","texto":"Hongos y bacterias del suelo"}],"derecha":[{"id":"b1","texto":"Que muchas plantas den frutos"},{"id":"b2","texto":"Absorber agua y amortiguar inundaciones"},{"id":"b3","texto":"Sombra y temperaturas más bajas"},{"id":"b4","texto":"Descomponer restos y fertilizar la tierra"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada uno de estos servicios tendría un costo enorme si hubiera que hacerlo con máquinas. Proteger un ecosistema muchas veces es la forma más barata de conservar lo que nos da."}},{"slug":"tronco-1.s1.p8","orden":8,"grupo":"tronco-1.s1.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un servicio de la naturaleza se pierde, siempre se puede reemplazar con tecnología sin costo extra.","razones":[{"id":"r1","texto":"Reemplazarlo cuesta dinero y energía, y a veces no alcanza"},{"id":"r2","texto":"La tecnología siempre es más barata que la naturaleza"},{"id":"r3","texto":"Los servicios de la naturaleza no tienen ningún valor económico"}]},"solucion":{"valor":false,"explicacion":"Algunos servicios se pueden reemplazar en parte (por ejemplo, con plantas potabilizadoras o polinización manual), pero cuesta dinero, energía y trabajo, y muchos no se pueden reemplazar del todo. Por eso cuidar el ecosistema suele ser mejor negocio que arreglar después.","clave":["r1"]}},{"slug":"tronco-1.s1.p9","orden":9,"grupo":"tronco-1.s1.p9","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá la idea central de esta sesión.","texto":"El ambiente tiene partes {{0}} y partes {{1}}, y lo importante es cómo se {{2}} entre sí.","banco":[{"id":"w1","texto":"vivas"},{"id":"w2","texto":"no vivas"},{"id":"w3","texto":"relacionan"},{"id":"w4","texto":"lejanas"},{"id":"w5","texto":"separadas"},{"id":"w6","texto":"artificiales"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Pensar en relaciones es la clave de todo el árbol: casi ningún problema ambiental se entiende mirando una sola parte."}},{"slug":"tronco-1.s1.p10","orden":10,"grupo":"tronco-1.s1.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Lucía dice: \"Yo vivo en un departamento en el centro, el ambiente no tiene nada que ver conmigo\". ¿Qué le responderías?","opciones":[{"id":"o1","texto":"Que el agua, la luz y la comida que usa en su departamento también son ambiente"},{"id":"o2","texto":"Que tiene razón: en la ciudad el ambiente ya está perdido y no vale la pena"},{"id":"o3","texto":"Que para cuidar el ambiente de verdad tendría que mudarse al campo"},{"id":"o4","texto":"Que el ambiente solo depende de lo que decidan los gobiernos y las empresas"}]},"solucion":{"clave":["o1"],"explicacion":"Justamente en las ciudades es donde más energía, agua y materiales se usan. Por eso lo que pasa en un departamento del centro también es un tema ambiental.","por_opcion":{"o3":"Mudarse no cambia nada de fondo: lo que cuenta es cómo se usan el agua, la energía y los materiales, estés donde estés."}}},{"slug":"tronco-1.s1.p11","orden":11,"grupo":"tronco-1.s1.p11","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená desde lo más cercano a vos hasta lo más amplio.","items":[{"id":"i1","texto":"Tu cuarto"},{"id":"i2","texto":"Tu casa"},{"id":"i3","texto":"Tu barrio"},{"id":"i4","texto":"Tu ciudad"},{"id":"i5","texto":"La cuenca del río donde está tu ciudad"}],"extremos":["Más cerca","Más amplio"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El ambiente funciona en escalas que se meten unas dentro de otras. Lo que hacés en tu cuarto (la luz, el agua) se suma a lo de tu casa, tu barrio y tu ciudad, y todo termina en el mismo río."}},{"slug":"tronco-1.s1.p12","orden":12,"grupo":"tronco-1.s1.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas decisiones de todos los días tienen que ver con el ambiente?","opciones":[{"id":"o1","texto":"Qué comés en el almuerzo"},{"id":"o2","texto":"Cómo vas a la escuela o al trabajo"},{"id":"o3","texto":"Cuánto tiempo dejás corriendo el agua caliente"},{"id":"o4","texto":"Qué hacés con la cáscara de una banana"},{"id":"o5","texto":"Ninguna: el ambiente se decide en otro lado"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Todas. Comida, transporte, agua y residuos son justamente las cuatro grandes puertas por donde una persona común afecta al ambiente, y también por donde lo puede mejorar."}},{"slug":"tronco-1.s1.p13","orden":13,"grupo":"tronco-1.s1.p13","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una plaza, las lombrices desaparecen porque el suelo se compactó por el paso de autos. ¿Qué es lo más probable que pase después?","opciones":[{"id":"o1","texto":"El suelo se vuelve más duro, absorbe menos agua y a las plantas les cuesta crecer"},{"id":"o2","texto":"No pasa nada importante: las lombrices no cumplen ninguna función en el suelo"},{"id":"o3","texto":"El pasto crece más rápido porque ya no hay lombrices que se coman sus raíces"},{"id":"o4","texto":"Llegan lombrices de otros lugares en pocos días y el suelo sigue igual que antes"}]},"solucion":{"clave":["o1"],"explicacion":"Las lombrices hacen túneles que airean el suelo y dejan pasar el agua, y mezclan restos orgánicos que lo fertilizan. Sin ellas, el suelo se degrada y eso afecta a las plantas: un efecto en cadena que empezó en algo que no se ve.","por_opcion":{"o4":"Si la causa (la compactación) sigue, las lombrices no vuelven: el problema no es la lombriz, es el suelo."}}}]},{"slug":"tronco-1.s2","orden":2,"tipo":"leccion","titulo_es":"Nada desaparece: la materia da vueltas","bajada_es":"Cuando \"tirás\" algo, no se va: cambia de lugar. El agua y el carbono lo muestran mejor que nada.","minutos":11,"pasos":[{"slug":"tronco-1.s2.p1","orden":1,"grupo":"tronco-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"\"Tirar\" es cambiar de lugar","cuerpo":["En la Tierra la materia no se crea ni se destruye: se transforma y cambia de lugar. El planeta es, en la práctica, un sistema cerrado para la materia: casi nada entra desde el espacio y casi nada sale.","Por eso \"tirar\" algo no lo hace desaparecer. Una botella que va a la basura termina en un relleno sanitario, en un río o reciclada en otra cosa. El humo de un auto se mezcla con el aire que respiramos. Siempre está en algún lado."],"destacado":{"valor":"0","texto":"kilos de materia desaparecen cuando algo \"se tira\": solo cambia de lugar o de forma."}},"solucion":{}},{"slug":"tronco-1.s2.p2","orden":2,"grupo":"tronco-1.s2.p2","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cuando quemamos basura, la basura desaparece del planeta.","razones":[{"id":"r1","texto":"La materia se transforma en gases, humo y cenizas, pero sigue existiendo"},{"id":"r2","texto":"El fuego destruye la materia por completo"},{"id":"r3","texto":"Solo desaparece si se quema a mucha temperatura"}]},"solucion":{"valor":false,"explicacion":"La combustión transforma la materia: parte se va al aire como gases (entre ellos dióxido de carbono) y partículas, y parte queda como cenizas. Nada desaparece; lo que cambia es dónde termina y en qué forma.","clave":["r1"]}},{"slug":"tronco-1.s2.p3","orden":3,"grupo":"tronco-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El agua da vueltas desde siempre","cuerpo":["El agua que tomás hoy es muy antigua: da vueltas por el planeta desde hace miles de millones de años. El sol calienta el agua de mares, ríos y suelos y la evapora; el vapor sube, se enfría y se condensa en nubes; las nubes dejan caer lluvia o nieve.","Esa agua corre por la superficie hacia los ríos, o se infiltra en el suelo y llega a las napas subterráneas. Las plantas también devuelven agua al aire por sus hojas. Tarde o temprano, casi toda vuelve al mar, y el ciclo sigue."],"lista":["Evaporación: el agua pasa a vapor","Condensación: el vapor forma nubes","Precipitación: lluvia, nieve o granizo","Escorrentía e infiltración: corre por la superficie o baja al suelo"]},"solucion":{}},{"slug":"tronco-1.s2.p4","orden":4,"grupo":"tronco-1.s2.p4","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el viaje de una gota de agua desde el mar.","items":[{"id":"i1","texto":"El sol calienta el mar y el agua se evapora"},{"id":"i2","texto":"El vapor sube, se enfría y forma nubes"},{"id":"i3","texto":"Las nubes dejan caer lluvia sobre la tierra"},{"id":"i4","texto":"El agua corre hacia un río o se infiltra en el suelo"},{"id":"i5","texto":"El río lleva el agua otra vez al mar"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es un ciclo: no tiene un principio real, pero el sol es el motor que lo mueve todo. Sin la energía del sol no habría evaporación y el agua no subiría."}},{"slug":"tronco-1.s2.p5","orden":5,"grupo":"tronco-1.s2.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte del ciclo del agua con lo que pasa.","izquierda":[{"id":"a1","texto":"Evaporación"},{"id":"a2","texto":"Condensación"},{"id":"a3","texto":"Precipitación"},{"id":"a4","texto":"Infiltración"}],"derecha":[{"id":"b1","texto":"El agua líquida pasa a vapor"},{"id":"b2","texto":"El vapor se enfría y forma gotitas en las nubes"},{"id":"b3","texto":"El agua cae como lluvia o nieve"},{"id":"b4","texto":"El agua baja por el suelo hacia las napas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Estos cuatro nombres vuelven a aparecer en la rama de Agua. Conviene tenerlos claros ahora: son el mapa de por dónde anda cada gota."}},{"slug":"tronco-1.s2.p6","orden":6,"grupo":"tronco-1.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El carbono también viaja","cuerpo":["El carbono es el elemento del que están hechos todos los seres vivos. Las plantas lo toman del aire como dióxido de carbono (CO₂) y, con la energía del sol, lo convierten en azúcares y madera. Los animales lo comen, y al respirar devuelven CO₂ al aire. Cuando un ser vivo muere, hongos y bacterias lo descomponen y también liberan carbono.","Parte del carbono quedó guardado bajo tierra durante millones de años en forma de carbón, petróleo y gas: son restos de seres vivos muy antiguos. Al quemarlos, ese carbono vuelve al aire en muy poco tiempo, mucho más rápido de lo que las plantas y los océanos pueden absorberlo."]},"solucion":{}},{"slug":"tronco-1.s2.p7","orden":7,"grupo":"tronco-1.s2.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido del carbono desde el aire hasta volver al aire.","items":[{"id":"i1","texto":"Una planta toma CO₂ del aire"},{"id":"i2","texto":"Con la luz del sol lo convierte en azúcares y hojas"},{"id":"i3","texto":"Un animal come la planta"},{"id":"i4","texto":"El animal respira y devuelve CO₂ al aire"},{"id":"i5","texto":"El carbono se destruye dentro del animal"},{"id":"i6","texto":"La planta fabrica carbono nuevo a partir de agua"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El carbono pasa de un lado a otro sin crearse ni destruirse. Las dos piezas que sobraban proponen justamente eso —crearlo o destruirlo—, y eso no pasa."}},{"slug":"tronco-1.s2.p8","orden":8,"grupo":"tronco-1.s2.p8","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué quemar petróleo, carbón o gas agrega CO₂ al aire más rápido de lo que la naturaleza lo absorbe?","opciones":[{"id":"o1","texto":"Porque libera de golpe carbono que estuvo guardado bajo tierra millones de años"},{"id":"o2","texto":"Porque el petróleo tiene mucho más carbono que un árbol del mismo peso"},{"id":"o3","texto":"Porque al quemarse, el fuego fabrica carbono nuevo que antes no existía"},{"id":"o4","texto":"Porque las plantas no pueden absorber el CO₂ que viene del petróleo"}]},"solucion":{"clave":["o1"],"explicacion":"El carbono de los combustibles fósiles estaba fuera del ciclo rápido. Quemarlos lo suma al aire de golpe, y las plantas y los océanos, aunque absorben una parte, no alcanzan a compensar ese ritmo.","por_opcion":{"o2":"No es eso: el problema no es cuánto carbono tiene cada cosa, sino que sale de un depósito que estaba fuera del ciclo."}}},{"slug":"tronco-1.s2.p9","orden":9,"grupo":"tronco-1.s2.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El CO₂ que exhala una persona al respirar es la principal causa del aumento de CO₂ en el aire."},"solucion":{"valor":false,"explicacion":"El carbono que exhalamos viene de la comida, que viene de plantas que lo tomaron del aire hace poco: es parte del ciclo rápido y se compensa. El aumento viene sobre todo de quemar combustibles fósiles y de la deforestación, que suman carbono que estaba guardado."}},{"slug":"tronco-1.s2.p10","orden":10,"grupo":"tronco-1.s2.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los que cierran el ciclo","cuerpo":["Si nada descompusiera los restos, el planeta estaría tapado de hojas, troncos y animales muertos. Los descomponedores —hongos, bacterias, lombrices y muchos insectos— rompen esos restos y devuelven sus nutrientes al suelo, donde las plantas los vuelven a usar.","Cuando esos restos terminan enterrados sin aire, por ejemplo en un relleno sanitario, la descomposición cambia y produce metano, un gas que calienta mucho la atmósfera. Por eso lo que hacemos con los restos de comida importa: lo verás en detalle en la rama de Residuos."]},"solucion":{}},{"slug":"tronco-1.s2.p11","orden":11,"grupo":"tronco-1.s2.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hacen los descomponedores en un bosque? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Rompen hojas y restos muertos"},{"id":"o2","texto":"Devuelven nutrientes al suelo"},{"id":"o3","texto":"Permiten que las plantas vuelvan a usar esa materia"},{"id":"o4","texto":"Fabrican agua nueva"},{"id":"o5","texto":"Hacen desaparecer la materia"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Los descomponedores no hacen desaparecer nada: transforman los restos en nutrientes y gases. Son los que convierten el final de un ser vivo en el comienzo de otro."}},{"slug":"tronco-1.s2.p12","orden":12,"grupo":"tronco-1.s2.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un folleto de una empresa dice lo siguiente. Marcá las frases que contradicen lo que aprendiste.","segmentos":[{"id":"s1","texto":"Nuestro camión retira tus residuos todos los días."},{"id":"s2","texto":"Una vez que salen de tu casa, desaparecen para siempre."},{"id":"s3","texto":"Los llevamos a un relleno sanitario controlado."},{"id":"s4","texto":"Al quemarlos, eliminamos toda la materia sin dejar rastros."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las frases que prometen que algo \"desaparece\" chocan con la idea central de esta sesión. La materia siempre termina en algún lugar.","por_opcion":{"s2":"Nada desaparece: los residuos van a un relleno, a una planta o terminan en el ambiente.","s4":"Quemar transforma la materia en gases, humo y cenizas; siempre deja rastros."}}},{"slug":"tronco-1.s2.p13","orden":13,"grupo":"tronco-1.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La materia no se {{0}} ni se {{1}}: se {{2}} y cambia de lugar.","banco":[{"id":"w1","texto":"crea"},{"id":"w2","texto":"destruye"},{"id":"w3","texto":"transforma"},{"id":"w4","texto":"recicla"},{"id":"w5","texto":"evapora"},{"id":"w6","texto":"multiplica"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Esta frase resume la sesión. Cada vez que escuches que algo \"se fue\", preguntate adónde fue."}}]},{"slug":"tronco-1.s3","orden":3,"tipo":"leccion","titulo_es":"La energía fluye y se degrada","bajada_es":"Toda la energía de los seres vivos viene del sol. En cada paso, una parte se pierde como calor.","minutos":11,"pasos":[{"slug":"tronco-1.s3.p1","orden":1,"grupo":"tronco-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El sol mueve casi todo","cuerpo":["Casi toda la energía que usan los seres vivos viene del sol. Las plantas, las algas y algunas bacterias capturan la luz con la fotosíntesis y la guardan en forma de azúcares. Todos los demás —herbívoros, carnívoros, hongos, nosotros— obtenemos energía comiendo lo que otro fabricó.","A diferencia de la materia, la energía no da vueltas en círculo: entra desde el sol, pasa de un ser vivo a otro, y en cada paso una parte se escapa como calor, que ya no sirve para hacer trabajo. Por eso los ecosistemas necesitan recibir sol todo el tiempo."],"destacado":{"valor":"≈10 %","texto":"de la energía de un nivel de la cadena alimentaria llega, en promedio, al nivel siguiente."}},"solucion":{}},{"slug":"tronco-1.s3.p2","orden":2,"grupo":"tronco-1.s3.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿De dónde sacan la energía las plantas?","opciones":[{"id":"o1","texto":"De la luz del sol, con la fotosíntesis"},{"id":"o2","texto":"Del suelo, que absorben por las raíces"},{"id":"o3","texto":"Del agua que absorben cuando llueve"},{"id":"o4","texto":"Del aire que respiran durante la noche"}]},"solucion":{"clave":["o1"],"explicacion":"Las raíces toman agua y minerales, y las hojas toman CO₂ del aire, pero la energía para armar azúcares con todo eso viene de la luz. Sin luz, la fotosíntesis se detiene.","por_opcion":{"o2":"Del suelo toman agua y nutrientes minerales, pero no la energía: esa viene de la luz."}}},{"slug":"tronco-1.s3.p3","orden":3,"grupo":"tronco-1.s3.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Quién fabrica su alimento y quién lo obtiene comiendo a otros?","grupos":[{"id":"g1","nombre":"Produce su alimento con la luz"},{"id":"g2","nombre":"Obtiene energía comiendo a otros"}],"items":[{"id":"i1","texto":"Un pasto"},{"id":"i2","texto":"Una vaca"},{"id":"i3","texto":"Un alga del río"},{"id":"i4","texto":"Un hornero"},{"id":"i5","texto":"Un ceibo"},{"id":"i6","texto":"Un hongo"},{"id":"i7","texto":"Una persona"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g2"},"explicacion":"Los productores (plantas, algas) son la puerta de entrada de la energía del sol. Los consumidores y los descomponedores dependen de ellos, aunque no los coman directamente."}},{"slug":"tronco-1.s3.p4","orden":4,"grupo":"tronco-1.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué se pierde energía en cada paso","cuerpo":["Cuando una vaca come pasto, no todo lo que come se convierte en carne. Una gran parte de esa energía la usa para vivir —moverse, respirar, mantener la temperatura del cuerpo— y se termina liberando como calor. Otra parte ni siquiera se digiere.","En promedio, solo alrededor del 10 % de la energía de un nivel pasa al siguiente. Es un promedio aproximado: varía según el ecosistema y el animal, pero siempre es mucho menos que el total. Esa pérdida explica por qué hay muchas más plantas que herbívoros y muchos más herbívoros que carnívoros."]},"solucion":{}},{"slug":"tronco-1.s3.p5","orden":5,"grupo":"tronco-1.s3.p5","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Cuánta energía llega arriba","planteo":"Un campo de pasto captura 10.000 unidades de energía del sol. ¿Cuánta energía llega a un carnívoro que come herbívoros que comen ese pasto?","pasos":["Pasto → herbívoros: pasa cerca del 10 %, o sea 10.000 × 0,10 = 1.000 unidades.","Herbívoros → carnívoro: otra vez cerca del 10 %, o sea 1.000 × 0,10 = 100 unidades."],"resultado":"Al carnívoro le llegan unas 100 unidades: el 1 % de lo que capturó el pasto. El resto se perdió como calor en el camino."},"solucion":{}},{"slug":"tronco-1.s3.p6","orden":6,"grupo":"tronco-1.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si unas algas capturan 50.000 unidades de energía, ¿cuántas llegan aproximadamente a los peces pequeños que las comen? (Usá la regla del 10 %.)","unidad":"unidades","decimales":0},"solucion":{"valor":5000,"tolerancia":100,"explicacion":"Un paso de la cadena: 50.000 × 0,10 = 5.000 unidades. El resto (45.000) se usó para vivir o se perdió como calor."}},{"slug":"tronco-1.s3.p7","orden":7,"grupo":"tronco-1.s3.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Siguiendo con el ejemplo anterior: si un pez grande come a esos peces pequeños, ¿cuántas unidades de las 50.000 iniciales le llegan aproximadamente?","unidad":"unidades","decimales":0},"solucion":{"valor":500,"tolerancia":10,"explicacion":"Son dos pasos: 50.000 × 0,10 = 5.000, y 5.000 × 0,10 = 500. En dos pasos de la cadena queda alrededor del 1 % de la energía inicial."}},{"slug":"tronco-1.s3.p8","orden":8,"grupo":"tronco-1.s3.p8","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos grupos de un campo según cuánta energía total contienen, de mayor a menor.","items":[{"id":"i1","texto":"Todas las plantas del campo"},{"id":"i2","texto":"Todos los insectos que comen plantas"},{"id":"i3","texto":"Todos los pájaros que comen esos insectos"},{"id":"i4","texto":"Los halcones que cazan esos pájaros"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Es la pirámide de energía: cada nivel tiene mucho menos que el anterior. Por eso los grandes depredadores siempre son pocos y necesitan territorios enormes.","valores":{"i1":"La base: capturan la energía del sol","i2":"Alrededor de una décima parte","i3":"Una décima parte de la anterior","i4":"Lo que queda arriba de todo"}}},{"slug":"tronco-1.s3.p9","orden":9,"grupo":"tronco-1.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los combustibles son sol antiguo","cuerpo":["El carbón, el petróleo y el gas se formaron con restos de plantas, algas y otros organismos que vivieron hace millones de años. La energía que guardan es, en el fondo, energía del sol que esos seres vivos capturaron entonces.","Es una reserva enorme pero que no se repone a escala humana: tarda millones de años en formarse y la estamos usando en pocos siglos. Además, al quemarla se libera el carbono guardado, como viste en la sesión anterior."]},"solucion":{}},{"slug":"tronco-1.s3.p10","orden":10,"grupo":"tronco-1.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La energía del petróleo es, en su origen, energía del sol.","razones":[{"id":"r1","texto":"Viene de organismos que capturaron la luz del sol hace millones de años"},{"id":"r2","texto":"El petróleo se fabrica solo en el centro de la Tierra, sin relación con los seres vivos"},{"id":"r3","texto":"Toda la energía viene de la luna"}]},"solucion":{"valor":true,"explicacion":"El petróleo se formó con restos de organismos que hace millones de años hicieron fotosíntesis o comieron a quienes la hacían. Esa energía solar quedó guardada en sus restos.","clave":["r1"]}},{"slug":"tronco-1.s3.p11","orden":11,"grupo":"tronco-1.s3.p11","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el camino de la energía desde el sol hasta un auto a nafta.","items":[{"id":"i1","texto":"Algas antiguas capturan la luz del sol"},{"id":"i2","texto":"Sus restos quedan enterrados durante millones de años"},{"id":"i3","texto":"Se transforman en petróleo"},{"id":"i4","texto":"El petróleo se refina y se convierte en nafta"},{"id":"i5","texto":"El motor quema la nafta y la energía mueve el auto (y mucha se pierde como calor)"},{"id":"i6","texto":"La nafta se fabrica con agua de mar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El auto a nafta funciona, en el fondo, con luz del sol de hace millones de años. Y, como en toda transformación, una buena parte se pierde como calor en el motor."}},{"slug":"tronco-1.s3.p12","orden":12,"grupo":"tronco-1.s3.p12","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un ecosistema no puede funcionar sin una entrada constante de energía, pero sí puede reutilizar la materia?","opciones":[{"id":"o1","texto":"Porque la materia circula en ciclos y la energía se degrada en calor en cada paso"},{"id":"o2","texto":"Porque la energía queda guardada en el suelo y con los años se termina agotando"},{"id":"o3","texto":"Porque la materia también se pierde en cada paso, solo que más despacio"},{"id":"o4","texto":"Porque las plantas destruyen la energía del sol al hacer la fotosíntesis"}]},"solucion":{"clave":["o1"],"explicacion":"Es la diferencia más importante de esta unidad: la materia circula, la energía fluye y se degrada. Por eso los seres vivos dependen del sol todos los días.","por_opcion":{"o3":"La materia no se pierde: da vueltas. Esa es justamente la diferencia con la energía."}}},{"slug":"tronco-1.s3.p13","orden":13,"grupo":"tronco-1.s3.p13","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conclusiones se desprenden de que se pierda energía en cada paso de una cadena alimentaria?","opciones":[{"id":"o1","texto":"Hay muchas más plantas que carnívoros en un ecosistema"},{"id":"o2","texto":"Los grandes depredadores necesitan territorios amplios"},{"id":"o3","texto":"Producir alimento de origen animal requiere más energía y más plantas que alimentarse directamente de plantas"},{"id":"o4","texto":"Los carnívoros tienen más energía total que las plantas"},{"id":"o5","texto":"La energía vuelve al sol al final de la cadena"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La tercera conclusión es la base de un tema que verás en Alimentación: cada paso extra de la cadena multiplica la cantidad de plantas, agua y tierra necesarias."}}]},{"slug":"tronco-1.s4","orden":4,"tipo":"leccion","titulo_es":"Sistemas: los efectos viajan","bajada_es":"Un cambio chico en un lugar puede terminar en un cambio grande en otro. Aprendé a seguir la cadena.","minutos":11,"pasos":[{"slug":"tronco-1.s4.p1","orden":1,"grupo":"tronco-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es un sistema","cuerpo":["Un sistema es un conjunto de partes que se relacionan y funcionan como un todo: un cuerpo, una ciudad, un bosque, el clima. Lo que define a un sistema no son sus partes sueltas sino sus conexiones.","Por eso, cuando se cambia una parte, el efecto no se queda ahí: viaja por las conexiones. A veces el efecto llega lejos, a veces tarda años en notarse y a veces termina volviendo sobre la causa."]},"solucion":{}},{"slug":"tronco-1.s4.p2","orden":2,"grupo":"tronco-1.s4.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es lo que más define a un sistema?","opciones":[{"id":"o1","texto":"Las relaciones entre sus partes"},{"id":"o2","texto":"La cantidad de partes que tiene"},{"id":"o3","texto":"Su tamaño"},{"id":"o4","texto":"Que sea natural y no artificial"}]},"solucion":{"clave":["o1"],"explicacion":"Un montón de piezas sueltas no es un sistema; el mismo montón conectado sí. Por eso, para entender un problema ambiental, hay que dibujar las conexiones.","por_opcion":{"o4":"Una ciudad o una red eléctrica también son sistemas: lo que importa son las conexiones, no si es natural."}}},{"slug":"tronco-1.s4.p3","orden":3,"grupo":"tronco-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Efectos en cadena: el castor en Tierra del Fuego","cuerpo":["En 1946 se llevaron castores canadienses a Tierra del Fuego para criarlos por su piel. Allí no tenían depredadores naturales, y se multiplicaron: hoy se cuentan por decenas de miles en la isla.","Los castores construyen diques que inundan valles enteros, y los árboles de los bosques fueguinos —que no evolucionaron junto a ellos— mueren ahogados o talados y se regeneran muy despacio. Una decisión que parecía chica cambió el paisaje de una región entera."]},"solucion":{}},{"slug":"tronco-1.s4.p4","orden":4,"grupo":"tronco-1.s4.p4","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de efectos de la llegada del castor a Tierra del Fuego.","items":[{"id":"i1","texto":"Se introducen castores sin depredadores naturales"},{"id":"i2","texto":"La población crece durante décadas"},{"id":"i3","texto":"Construyen diques en arroyos y ríos"},{"id":"i4","texto":"Los valles se inundan y los árboles mueren"},{"id":"i5","texto":"El bosque nativo se pierde en grandes áreas"},{"id":"i6","texto":"Los castores comen peces y dejan los ríos vacíos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada eslabón causa el siguiente. El señuelo es falso: los castores son herbívoros; el daño viene de los diques y la tala, no de comer peces."}},{"slug":"tronco-1.s4.p5","orden":5,"grupo":"tronco-1.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una especie traída de otro lugar siempre se integra sin problemas porque el ecosistema se adapta."},"solucion":{"valor":false,"explicacion":"Muchas especies introducidas no causan problemas, pero algunas se vuelven invasoras: sin sus depredadores o competidores de origen se multiplican y desplazan a las nativas. El castor, el ligustro o la rana toro son ejemplos en Argentina."}},{"slug":"tronco-1.s4.p6","orden":6,"grupo":"tronco-1.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Retroalimentación: cuando el efecto vuelve sobre la causa","cuerpo":["A veces un efecto termina empujando a su propia causa. Si la empuja más fuerte, se habla de retroalimentación que amplifica: es lo que pasa con el hielo polar. El hielo blanco refleja mucha luz del sol; si se derrite, queda mar oscuro que absorbe más calor, lo que derrite más hielo.","Si la empuja al revés, se habla de retroalimentación que estabiliza, como un termostato: si hace calor, prende el aire; cuando baja la temperatura, lo apaga. Los ecosistemas tienen muchas de estas, y por eso resisten cambios... hasta cierto límite."]},"solucion":{}},{"slug":"tronco-1.s4.p7","orden":7,"grupo":"tronco-1.s4.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el círculo del hielo polar que se derrite.","items":[{"id":"i1","texto":"La temperatura sube"},{"id":"i2","texto":"Se derrite parte del hielo"},{"id":"i3","texto":"Queda expuesto mar oscuro que absorbe más calor del sol"},{"id":"i4","texto":"La zona se calienta todavía más"},{"id":"i5","texto":"El mar oscuro refleja más luz que el hielo"},{"id":"i6","texto":"El hielo derretido enfría el aire del planeta"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El último eslabón vuelve al primero: por eso es un círculo que se amplifica. Los señuelos dicen lo contrario de lo que pasa: el hielo refleja más, no el mar."}},{"slug":"tronco-1.s4.p8","orden":8,"grupo":"tronco-1.s4.p8","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Estas retroalimentaciones amplifican el cambio o lo estabilizan?","grupos":[{"id":"g1","nombre":"Amplifica el cambio"},{"id":"g2","nombre":"Estabiliza"}],"items":[{"id":"i1","texto":"Menos hielo → más calor absorbido → menos hielo"},{"id":"i2","texto":"Más conejos → más comida para los zorros → más zorros → menos conejos"},{"id":"i3","texto":"Más incendios → menos bosque que da humedad → suelo más seco → más incendios"},{"id":"i4","texto":"Hace calor → sudás → el sudor se evapora y te enfría"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"La pregunta clave es: ¿el efecto empuja la causa en el mismo sentido o en sentido contrario? Mismo sentido amplifica; contrario estabiliza."}},{"slug":"tronco-1.s4.p9","orden":9,"grupo":"tronco-1.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los retrasos engañan","cuerpo":["En los sistemas, muchas causas tardan en mostrar su efecto. Un árbol que se planta hoy da sombra en diez años; una napa contaminada puede tardar décadas en limpiarse; el CO₂ que se emite hoy sigue calentando el planeta durante mucho tiempo.","Los retrasos hacen que a veces parezca que \"no pasa nada\" y se reaccione tarde. Pensar en sistemas es también pensar en el tiempo: qué va a pasar después, no solo ahora."]},"solucion":{}},{"slug":"tronco-1.s4.p10","orden":10,"grupo":"tronco-1.s4.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una fábrica tira residuos a un arroyo y durante un año no se nota nada raro en el río grande al que llega. ¿Qué conclusión es la más correcta?","opciones":[{"id":"o1","texto":"No se puede concluir que no haya daño: los efectos pueden tardar y acumularse"},{"id":"o2","texto":"Que los residuos son inofensivos, porque si no ya se habría notado algo"},{"id":"o3","texto":"Que el río grande tiene tanta agua que nunca se va a contaminar por eso"},{"id":"o4","texto":"Que el arroyo limpia solo cualquier residuo antes de llegar al río"}]},"solucion":{"clave":["o1"],"explicacion":"Los retrasos engañan: la ausencia de un efecto visible no prueba que no exista. Por eso se mide y se controla antes de que el daño se vea a simple vista.","por_opcion":{"o3":"Diluir no es eliminar: muchas sustancias se acumulan en el sedimento o en los seres vivos."}}},{"slug":"tronco-1.s4.p11","orden":11,"grupo":"tronco-1.s4.p11","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas son consecuencias no buscadas de una decisión? Marcá todas.","opciones":[{"id":"o1","texto":"Se pavimenta un barrio para evitar el barro y aumentan las inundaciones porque el agua ya no se infiltra"},{"id":"o2","texto":"Se introduce una especie para controlar una plaga y termina siendo plaga ella misma"},{"id":"o3","texto":"Se ensancha una avenida para bajar el tránsito y a los años hay más autos que antes"},{"id":"o4","texto":"Se planta un árbol nativo y da sombra"},{"id":"o5","texto":"Se arregla una canilla y se pierde menos agua"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Las tres primeras son ejemplos reales de efectos no buscados; las otras dos son efectos buscados y logrados. Muchos problemas ambientales nacieron de soluciones que no miraron el sistema entero."}},{"slug":"tronco-1.s4.p12","orden":12,"grupo":"tronco-1.s4.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada idea de sistemas con su ejemplo.","izquierda":[{"id":"a1","texto":"Efecto en cadena"},{"id":"a2","texto":"Retroalimentación que amplifica"},{"id":"a3","texto":"Retroalimentación que estabiliza"},{"id":"a4","texto":"Retraso"}],"derecha":[{"id":"b1","texto":"Menos lombrices → suelo compacto → menos plantas"},{"id":"b2","texto":"Menos hielo → más calor → menos hielo"},{"id":"b3","texto":"Hace calor → transpirás → te enfriás"},{"id":"b4","texto":"El árbol que plantás hoy da sombra en diez años"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Con estas cuatro ideas se puede analizar casi cualquier problema ambiental. Van a volver en Clima, en Agua y en Comunidad."}},{"slug":"tronco-1.s4.p13","orden":13,"grupo":"tronco-1.s4.p13","tipo":"opcion","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un lago, se echan fertilizantes de campos cercanos. Crecen muchas algas, que al morir se descomponen y consumen el oxígeno del agua. ¿Qué es lo más probable que pase con los peces?","opciones":[{"id":"o1","texto":"Muchos mueren por falta de oxígeno"},{"id":"o2","texto":"Crecen más porque tienen más algas para comer"},{"id":"o3","texto":"No les pasa nada: el oxígeno no depende de las algas"},{"id":"o4","texto":"Se mudan todos a otro lago sin problemas"}]},"solucion":{"clave":["o1"],"explicacion":"Es un efecto en cadena muy común llamado eutrofización: más nutrientes → más algas → más descomposición → menos oxígeno → mueren peces. Lo que empezó en un campo termina en un lago.","por_opcion":{"o4":"En un lago cerrado los peces no tienen adónde ir: el efecto les llega de lleno."}}}]},{"slug":"tronco-1.s5","orden":5,"tipo":"leccion","titulo_es":"Lo que se renueva y lo que no","bajada_es":"Hay recursos que se reponen y otros que no. Y hasta lo renovable se agota si se usa más rápido de lo que se repone.","minutos":11,"pasos":[{"slug":"tronco-1.s5.p1","orden":1,"grupo":"tronco-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Renovables y no renovables","cuerpo":["Un recurso renovable se repone por procesos naturales en un tiempo que importa para las personas: el agua de lluvia, la madera de un bosque, los peces de un río, la luz del sol, el viento.","Un recurso no renovable tarda tanto en formarse —miles o millones de años— que, a escala humana, lo que se usa no vuelve: el petróleo, el gas, el carbón y los minerales como el cobre o el litio. De estos hay una cantidad fija, aunque sea grande."]},"solucion":{}},{"slug":"tronco-1.s5.p2","orden":2,"grupo":"tronco-1.s5.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá estos recursos.","grupos":[{"id":"g1","nombre":"Renovable"},{"id":"g2","nombre":"No renovable"}],"items":[{"id":"i1","texto":"Luz del sol"},{"id":"i2","texto":"Petróleo"},{"id":"i3","texto":"Viento"},{"id":"i4","texto":"Gas natural"},{"id":"i5","texto":"Madera de un bosque manejado"},{"id":"i6","texto":"Cobre"},{"id":"i7","texto":"Peces de un río"},{"id":"i8","texto":"Carbón"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1","i8":"g2"},"explicacion":"Los renovables se reponen en tiempos humanos; los no renovables tardan millones de años. Ojo: que algo sea renovable no quiere decir que sea infinito, como vas a ver ahora."}},{"slug":"tronco-1.s5.p3","orden":3,"grupo":"tronco-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El ritmo lo es todo","cuerpo":["Un recurso renovable funciona como una cuenta que recibe un depósito por año. Si se saca menos que ese depósito, la cuenta se mantiene. Si se saca más, la cuenta baja aunque el recurso sea \"renovable\".","Así se agotan pesquerías, se secan napas subterráneas y se degradan suelos. Lo que importa no es solo si un recurso se renueva, sino si se usa más rápido de lo que se repone."],"destacado":{"valor":"Uso ≤ reposición","texto":"es la condición para que un recurso renovable dure en el tiempo."}},"solucion":{}},{"slug":"tronco-1.s5.p4","orden":4,"grupo":"tronco-1.s5.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Una napa que baja","planteo":"Una napa subterránea recibe 100 millones de litros por año de lluvia que se infiltra. Un pueblo bombea 130 millones de litros por año.","pasos":["Entrada por año: 100 millones de litros.","Salida por año: 130 millones de litros.","Balance: 100 − 130 = −30 millones de litros por año."],"resultado":"La napa pierde 30 millones de litros por año aunque el agua sea renovable. Si el bombeo sigue igual, el nivel baja año tras año."},"solucion":{}},{"slug":"tronco-1.s5.p5","orden":5,"grupo":"tronco-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una napa recibe 80 millones de litros por año de lluvia y se le extraen 95 millones por año. ¿Cuántos millones de litros pierde por año?","unidad":"millones de litros por año","decimales":0},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"Balance: entrada 80 − salida 95 = −15. La napa pierde 15 millones de litros por año: el recurso es renovable, pero se lo usa más rápido de lo que se repone."}},{"slug":"tronco-1.s5.p5.v2","orden":5,"grupo":"tronco-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una napa recibe 120 millones de litros por año de lluvia y se le extraen 150 millones por año. ¿Cuántos millones de litros pierde por año?","unidad":"millones de litros por año","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"Balance: entrada 120 − salida 150 = −30. La napa pierde 30 millones de litros por año: el recurso es renovable, pero se lo usa más rápido de lo que se repone."}},{"slug":"tronco-1.s5.p5.v3","orden":5,"grupo":"tronco-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una napa recibe 60 millones de litros por año de lluvia y se le extraen 72 millones por año. ¿Cuántos millones de litros pierde por año?","unidad":"millones de litros por año","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"Balance: entrada 60 − salida 72 = −12. La napa pierde 12 millones de litros por año: el recurso es renovable, pero se lo usa más rápido de lo que se repone."}},{"slug":"tronco-1.s5.p6","orden":6,"grupo":"tronco-1.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los peces se reproducen, pescar todo lo que se quiera nunca puede agotar una población.","razones":[{"id":"r1","texto":"Si se pesca más rápido de lo que se reproducen, la población cae"},{"id":"r2","texto":"Los peces se reproducen infinitamente, así que no hay límite"},{"id":"r3","texto":"Solo se agotan los recursos no renovables"}]},"solucion":{"valor":false,"explicacion":"Si se pesca más rápido de lo que la población se reproduce, disminuye año a año hasta colapsar. Pasó en muchas pesquerías del mundo. Por eso existen cupos, vedas y tamaños mínimos.","clave":["r1"]}},{"slug":"tronco-1.s5.p7","orden":7,"grupo":"tronco-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La huella y el día del sobregiro","cuerpo":["La huella ecológica estima cuánta superficie productiva del planeta —campos, bosques, mares— hace falta para producir lo que consumimos y absorber lo que emitimos. Se compara con la biocapacidad: lo que el planeta regenera en un año.","Según la Global Footprint Network, desde hace décadas la humanidad usa en un año más de lo que el planeta regenera en ese año. El día del calendario en que se agota lo del año se llama Día del Sobregiro de la Tierra, y en los últimos años cayó entre fines de julio y principios de agosto."]},"solucion":{}},{"slug":"tronco-1.s5.p8","orden":8,"grupo":"tronco-1.s5.p8","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué significa que el Día del Sobregiro de la Tierra caiga a fines de julio?","opciones":[{"id":"o1","texto":"Que para esa fecha la humanidad ya usó lo que el planeta regenera en todo el año"},{"id":"o2","texto":"Que a partir de esa fecha el planeta deja de producir recursos hasta enero"},{"id":"o3","texto":"Que ese día se terminan las reservas de petróleo y de gas del mundo"},{"id":"o4","texto":"Que ese día la humanidad consume más energía que cualquier otro día del año"}]},"solucion":{"clave":["o1"],"explicacion":"Es como una cuenta que en julio ya gastó el sueldo de todo el año: el resto del año se vive \"en rojo\", sacando de los ahorros del planeta (bosques, peces, suelos) y acumulando CO₂.","por_opcion":{"o3":"El sobregiro no mide reservas de combustibles: compara el consumo con lo que la naturaleza regenera por año."}}},{"slug":"tronco-1.s5.p9","orden":9,"grupo":"tronco-1.s5.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos recursos según cuánto tardan en reponerse, del más rápido al más lento.","items":[{"id":"i1","texto":"La luz del sol (llega cada día)"},{"id":"i2","texto":"Una cosecha de lechuga (semanas)"},{"id":"i3","texto":"Un bosque talado (décadas)"},{"id":"i4","texto":"El petróleo (millones de años)"}],"extremos":["Más rápido","Más lento"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El tiempo de reposición es lo que separa un recurso renovable de uno no renovable. Un bosque es renovable, pero tarda décadas: talarlo más rápido que eso lo agota."}},{"slug":"tronco-1.s5.p10","orden":10,"grupo":"tronco-1.s5.p10","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué estrategias ayudan a que un recurso renovable no se agote?","opciones":[{"id":"o1","texto":"Usarlo a un ritmo menor que el de reposición"},{"id":"o2","texto":"Medir cuánto hay y cuánto se usa"},{"id":"o3","texto":"Proteger lo que lo repone (por ejemplo, el suelo que deja infiltrar la lluvia)"},{"id":"o4","texto":"Usarlo lo más rápido posible antes de que lo usen otros"},{"id":"o5","texto":"Ignorarlo porque \"es renovable\""}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Las tres primeras son la base de la gestión de recursos. La cuarta es la trampa más común: cuando muchos usan lo mismo sin reglas, todos terminan perdiendo."}},{"slug":"tronco-1.s5.p11","orden":11,"grupo":"tronco-1.s5.p11","tipo":"estimar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Para ponerle números al sobregiro: si la humanidad usa en un año lo que el planeta regenera en ese año multiplicado por 1,7, ¿cuántos días \"le alcanza\" lo del año? Estimá.","min":100,"max":365,"paso":1,"unidad":"días","escala":"lineal"},"solucion":{"valor":215,"banda":"lineal","explicacion":"365 ÷ 1,7 ≈ 215 días: lo del año se agota a comienzos de agosto. Es exactamente la lógica del Día del Sobregiro."}},{"slug":"tronco-1.s5.p12","orden":12,"grupo":"tronco-1.s5.p12","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este razonamiento y marcá las partes equivocadas.","segmentos":[{"id":"s1","texto":"El agua es un recurso renovable,"},{"id":"s2","texto":"así que podemos bombear de la napa toda el agua que queramos"},{"id":"s3","texto":"y la lluvia siempre la va a reponer al mismo ritmo"},{"id":"s4","texto":"porque el ciclo del agua existe desde hace millones de años."}]},"solucion":{"clave":["s2","s3"],"explicacion":"El ciclo del agua existe, y el agua es renovable, pero eso no garantiza que una napa en particular aguante cualquier ritmo de extracción.","por_opcion":{"s2":"Renovable no quiere decir ilimitado: si se bombea más de lo que se infiltra, la napa baja.","s3":"La reposición depende de la lluvia y del suelo; si se impermeabiliza, se infiltra menos."}}},{"slug":"tronco-1.s5.p13","orden":13,"grupo":"tronco-1.s5.p13","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas situaciones según qué tan sostenible es el uso del recurso, de más a menos.","items":[{"id":"i1","texto":"Se pescan 60 toneladas de una especie que repone 100 por año"},{"id":"i2","texto":"Se pescan 100 toneladas de una especie que repone 100 por año"},{"id":"i3","texto":"Se pescan 150 toneladas de una especie que repone 100 por año"},{"id":"i4","texto":"Se pesca todo lo que se encuentra, sin medir"}],"extremos":["Más sostenible","Menos sostenible"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Lo sostenible no es \"no usar\", es usar por debajo de la reposición y medir para saber dónde se está.","valores":{"i1":"Uso menor a la reposición: la población se mantiene","i2":"Justo en el límite: cualquier mal año la hace bajar","i3":"Sobreexplotación: la población cae","i4":"Ni siquiera se sabe cuánto se está perdiendo"}}}]},{"slug":"tronco-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: todo está conectado","bajada_es":"Todo lo de la unidad mezclado, empezando por lo que más te costó.","minutos":8,"pasos":[{"slug":"tronco-1.s6.p1","orden":1,"grupo":"tronco-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Todo está conectado». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"tronco-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el arroyo del barrio","bajada_es":"Un caso real de punta a punta. Aprobalo para hacer crecer el tronco y abrir las ramas.","minutos":10,"pasos":[{"slug":"tronco-1.s7.p1","orden":1,"grupo":"tronco-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["En un barrio del conurbano corre un arroyo que hace veinte años tenía peces, sauces en las orillas y chicos que se metían a jugar. Hoy tiene poca agua limpia, olor en verano y, cuando llueve fuerte, se desborda.","En esos veinte años pasaron varias cosas: se pavimentaron las calles cercanas, se construyeron casas en la orilla, se talaron sauces, y algunas casas y un taller conectaron sus desagües al arroyo. Con lo que aprendiste en la unidad, vas a analizar qué pasó."]},"solucion":{}},{"slug":"tronco-1.s7.p2","orden":2,"grupo":"tronco-1.s7.p2","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué partes vivas y no vivas del ambiente del arroyo cambiaron en estos veinte años?","opciones":[{"id":"o1","texto":"Los peces (parte viva)"},{"id":"o2","texto":"Los sauces de las orillas (parte viva)"},{"id":"o3","texto":"La calidad del agua (parte no viva)"},{"id":"o4","texto":"El suelo de alrededor, ahora pavimentado (parte no viva)"},{"id":"o5","texto":"Nada: el arroyo es el mismo porque sigue en el mismo lugar"}],"contexto":"Un arroyo del conurbano: hace veinte años tenía peces y sauces; hoy tiene agua sucia y se desborda cuando llueve."},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cambiaron partes vivas y no vivas, y lo importante es que cambiaron juntas: cada cambio empujó a otros."}},{"slug":"tronco-1.s7.p3","orden":3,"grupo":"tronco-1.s7.p3","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena que explica por qué el arroyo ahora se desborda.","items":[{"id":"i1","texto":"Se pavimentan las calles cercanas"},{"id":"i2","texto":"La lluvia ya no se infiltra en el suelo"},{"id":"i3","texto":"Toda el agua corre por las calles hacia el arroyo al mismo tiempo"},{"id":"i4","texto":"El arroyo recibe más agua de la que puede llevar y se desborda"},{"id":"i5","texto":"El pavimento hace que llueva más"},{"id":"i6","texto":"Los peces tapan el cauce"}],"largo":4,"contexto":"Un arroyo del conurbano: se pavimentaron las calles cercanas y se construyó sobre las orillas."},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El pavimento no cambia la lluvia: cambia a dónde va. El agua que antes se infiltraba ahora llega toda junta y rápido al arroyo."}},{"slug":"tronco-1.s7.p4","orden":4,"grupo":"tronco-1.s7.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Algunas casas conectan sus desagües cloacales al arroyo. ¿Qué pasa con esa materia?","opciones":[{"id":"o1","texto":"No desaparece: queda en el agua, se acumula en el fondo y viaja río abajo"},{"id":"o2","texto":"El arroyo la limpia sola en unas horas gracias a la corriente"},{"id":"o3","texto":"Se evapora con el calor del verano y deja el agua limpia"},{"id":"o4","texto":"Se diluye tanto al mezclarse que deja de existir como contaminante"}]},"solucion":{"clave":["o1"],"explicacion":"Es la idea de la segunda sesión: nada desaparece. Lo que entra al arroyo termina en su fondo, en sus seres vivos o río abajo, en el río grande.","por_opcion":{"o2":"Un arroyo puede depurar un poco de materia orgánica, pero con descargas constantes se satura y pierde el oxígeno."}}},{"slug":"tronco-1.s7.p5","orden":5,"grupo":"tronco-1.s7.p5","tipo":"cadena","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena que explica por qué desaparecieron los peces.","items":[{"id":"i1","texto":"Llegan desagües con mucha materia orgánica y nutrientes"},{"id":"i2","texto":"Crecen algas y bacterias que descomponen esa materia"},{"id":"i3","texto":"La descomposición consume el oxígeno del agua"},{"id":"i4","texto":"Los peces no tienen oxígeno suficiente y mueren o se van"},{"id":"i5","texto":"Los peces se comieron toda la materia orgánica y murieron de indigestión"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Es la misma cadena del lago que viste en la sesión de sistemas: más nutrientes, más descomposición, menos oxígeno."}},{"slug":"tronco-1.s7.p6","orden":6,"grupo":"tronco-1.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Los vecinos proponen soluciones. ¿Atacan la causa o solo el síntoma?","grupos":[{"id":"g1","nombre":"Ataca una causa"},{"id":"g2","nombre":"Solo alivia el síntoma"}],"items":[{"id":"i1","texto":"Conectar las casas a la red cloacal"},{"id":"i2","texto":"Echar perfume en el agua para tapar el olor"},{"id":"i3","texto":"Volver a plantar sauces y dejar orillas sin cemento"},{"id":"i4","texto":"Sacar los peces muertos cada semana"},{"id":"i5","texto":"Hacer veredas y plazas que dejen infiltrar la lluvia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Pensar en sistemas es buscar las causas. Tapar el olor no cambia la cadena; conectar las cloacas y devolverle suelo y árboles a la orilla sí."}},{"slug":"tronco-1.s7.p7","orden":7,"grupo":"tronco-1.s7.p7","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un funcionario dice: \"Plantamos sauces en la orilla hace un mes y el arroyo sigue igual: no sirvió\". ¿Qué le falta considerar?","opciones":[{"id":"o1","texto":"Los retrasos: un árbol tarda años en crecer y en mostrar su efecto"},{"id":"o2","texto":"Que los sauces no tienen ninguna relación con la calidad del agua"},{"id":"o3","texto":"Que habría que plantar árboles exóticos, que crecen más rápido"},{"id":"o4","texto":"Que un arroyo contaminado ya nunca se puede recuperar"}]},"solucion":{"clave":["o1"],"explicacion":"Los retrasos engañan. Un sauce tarda años en sostener la orilla, dar sombra y bajar la temperatura del agua. Evaluar a un mes es evaluar demasiado pronto.","por_opcion":{"o3":"Los sauces criollos son nativos de estas orillas: el problema no es la especie, es el tiempo."}}},{"slug":"tronco-1.s7.p8","orden":8,"grupo":"tronco-1.s7.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el agua del arroyo es un recurso renovable, se va a recuperar sola aunque sigan llegando los desagües.","razones":[{"id":"r1","texto":"Mientras sigan las descargas, la causa del problema sigue presente"},{"id":"r2","texto":"El agua renovable se limpia sola siempre"},{"id":"r3","texto":"La lluvia elimina cualquier contaminación en un día"}]},"solucion":{"valor":false,"explicacion":"La recuperación depende de que las descargas paren. Mientras la causa siga, el arroyo no se recupera, por más que el agua se renueve con la lluvia.","clave":["r1"]}},{"slug":"tronco-1.s7.p9","orden":9,"grupo":"tronco-1.s7.p9","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas acciones según cuánto atacan la causa principal de la mala calidad del agua, de más a menos.","items":[{"id":"i1","texto":"Conectar todas las casas y el taller a la cloaca"},{"id":"i2","texto":"Controlar que el taller no tire aceites"},{"id":"i3","texto":"Plantar sauces en las orillas"},{"id":"i4","texto":"Poner carteles de \"no tirar basura\""}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Todas suman, pero no pesan lo mismo. Priorizar por impacto es una idea que vas a usar en todo el árbol.","valores":{"i1":"Corta la entrada principal de contaminación","i2":"Corta una fuente puntual y tóxica","i3":"Ayuda a la orilla y al agua, pero no frena las descargas","i4":"Útil, pero no toca las descargas de los desagües"}}},{"slug":"tronco-1.s7.p10","orden":10,"grupo":"tronco-1.s7.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué idea de la unidad resume mejor lo que le pasó al arroyo?","opciones":[{"id":"o1","texto":"Muchos cambios chicos y conectados que se sumaron durante años"},{"id":"o2","texto":"Una sola causa: que ahora llueve más que hace veinte años"},{"id":"o3","texto":"Mala suerte: los arroyos urbanos se arruinan solos con el tiempo"},{"id":"o4","texto":"Que los peces se fueron y dejaron de limpiar el agua del arroyo"}]},"solucion":{"clave":["o1"],"explicacion":"Es un sistema: pavimento, orillas, desagües y árboles se afectaron entre sí. La buena noticia es la misma: si los cambios se suman para mal, también se pueden sumar para bien.","por_opcion":{"o4":"Los peces son un síntoma, no una causa."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"tronco-2","rama":"tronco","orden":2,"nivel":0,"titulo_es":"Medir para entender","bajada_es":"Litros, kilovatios hora, kilos de CO₂: aprendé a leer y comparar los números del ambiente sin perderte en el camino.","objetivos_es":["Convertir entre las unidades que más aparecen: litros, metros cúbicos, gramos, kilos y toneladas","Distinguir potencia (kW) de energía (kWh) y calcular cuánto consume un aparato","Explicar qué es el CO₂ equivalente y por qué el metano pesa más que el CO₂","Leer un dato por persona, por año o por unidad sin confundirlo con un total","Comparar acciones por orden de magnitud para saber qué pesa de verdad"],"repasa":["tronco-1"],"requiere_tronco":0,"fuentes":["ipcc-ar6","ipcc-ar6-syr","owid-co2","owid-energia","iea-eficiencia","wynes-nicholas-2017","inventario-gei-ar"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"tronco-2.s1","orden":1,"tipo":"leccion","titulo_es":"Las unidades de todos los días","bajada_es":"Litros, kilos y metros cúbicos: la base para leer cualquier número del ambiente.","minutos":10,"pasos":[{"slug":"tronco-2.s1.p1","orden":1,"grupo":"tronco-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un número sin unidad no dice nada","cuerpo":["Si alguien te dice \"gastamos 150\", no sabés si son 150 litros, 150 kilos o 150 pesos. En ambiente los números vienen siempre con una unidad, y la unidad es la mitad del dato.","Las más comunes son tres familias: volumen (litros y metros cúbicos, para el agua), masa (gramos, kilos y toneladas, para residuos, alimentos y emisiones) y energía (kilovatios hora, para la electricidad)."],"lista":["Volumen: 1 litro = 1.000 mililitros · 1 metro cúbico (m³) = 1.000 litros","Masa: 1 kilo = 1.000 gramos · 1 tonelada = 1.000 kilos","Energía: 1 kilovatio hora (kWh) = 1.000 vatios hora (Wh)"]},"solucion":{}},{"slug":"tronco-2.s1.p2","orden":2,"grupo":"tronco-2.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada cantidad con la unidad que tiene sentido.","izquierda":[{"id":"a1","texto":"El agua de una ducha"},{"id":"a2","texto":"La basura de un mes en tu casa"},{"id":"a3","texto":"La electricidad de la factura"},{"id":"a4","texto":"La distancia a la escuela"}],"derecha":[{"id":"b1","texto":"Litros"},{"id":"b2","texto":"Kilos"},{"id":"b3","texto":"Kilovatios hora (kWh)"},{"id":"b4","texto":"Kilómetros"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada magnitud tiene su unidad. Mezclarlas es el error más común al leer un dato ambiental: \"litros de CO₂\" o \"kilos de electricidad\" no existen."}},{"slug":"tronco-2.s1.p3","orden":3,"grupo":"tronco-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El prefijo multiplica","cuerpo":["Los prefijos son atajos para no escribir ceros. \"Kilo\" significa mil: un kilómetro son mil metros, un kilogramo mil gramos, un kilovatio mil vatios. \"Mili\" significa milésima: un mililitro es la milésima parte de un litro.","\"Mega\" es un millón y \"giga\" mil millones. Por eso una central eléctrica se mide en megavatios y un país en gigavatios hora: son las mismas unidades con prefijos más grandes."],"destacado":{"valor":"k = 1.000","texto":"kilo multiplica por mil: 3 kWh son 3.000 Wh, y 2 kg son 2.000 g."}},"solucion":{}},{"slug":"tronco-2.s1.p4","orden":4,"grupo":"tronco-2.s1.p4","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá las equivalencias.","texto":"1 metro cúbico son {{0}}, y 1 tonelada son {{1}}.","banco":[{"id":"w1","texto":"1.000 litros"},{"id":"w2","texto":"1.000 kilos"},{"id":"w3","texto":"100 litros"},{"id":"w4","texto":"10 kilos"},{"id":"w5","texto":"1.000.000 litros"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Metro cúbico y tonelada son las \"unidades grandes\" del agua y de la masa. Las dos equivalen a mil de la unidad chica, así que se aprenden juntas."}},{"slug":"tronco-2.s1.p5","orden":5,"grupo":"tronco-2.s1.p5","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Pasar de mililitros a litros","planteo":"Una canilla gotea y en una hora llena un vaso de 250 mililitros. ¿Cuántos litros son en un día?","pasos":["En un día hay 24 horas: 250 ml × 24 = 6.000 ml.","Para pasar a litros se divide por mil: 6.000 ÷ 1.000 = 6 litros."],"resultado":"La canilla pierde 6 litros por día. Primero se hace la cuenta en la unidad cómoda y al final se convierte."},"solucion":{}},{"slug":"tronco-2.s1.p6","orden":6,"grupo":"tronco-2.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una botella tiene 500 mililitros. ¿Cuántos litros son?","unidad":"litros","decimales":2},"solucion":{"valor":0.5,"tolerancia":0.01,"explicacion":"Mililitro es la milésima parte de un litro: 500 ÷ 1.000 = 0,5 litros."}},{"slug":"tronco-2.s1.p6.v2","orden":6,"grupo":"tronco-2.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una botella tiene 750 mililitros. ¿Cuántos litros son?","unidad":"litros","decimales":2},"solucion":{"valor":0.75,"tolerancia":0.015,"explicacion":"Mililitro es la milésima parte de un litro: 750 ÷ 1.000 = 0,75 litros."}},{"slug":"tronco-2.s1.p6.v3","orden":6,"grupo":"tronco-2.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una botella tiene 300 mililitros. ¿Cuántos litros son?","unidad":"litros","decimales":2},"solucion":{"valor":0.3,"tolerancia":0.006,"explicacion":"Mililitro es la milésima parte de un litro: 300 ÷ 1.000 = 0,3 litros."}},{"slug":"tronco-2.s1.p6.v4","orden":6,"grupo":"tronco-2.s1.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una botella tiene 1.200 mililitros. ¿Cuántos litros son?","unidad":"litros","decimales":2},"solucion":{"valor":1.2,"tolerancia":0.024,"explicacion":"Mililitro es la milésima parte de un litro: 1.200 ÷ 1.000 = 1,2 litros."}},{"slug":"tronco-2.s1.p7","orden":7,"grupo":"tronco-2.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La factura del agua de una casa marca 12 m³ en el mes. ¿Cuántos litros son?","unidad":"litros","decimales":0},"solucion":{"valor":12000,"tolerancia":240,"explicacion":"Cada metro cúbico son 1.000 litros: 12 × 1.000 = 12.000 litros."}},{"slug":"tronco-2.s1.p7.v2","orden":7,"grupo":"tronco-2.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La factura del agua de una casa marca 18 m³ en el mes. ¿Cuántos litros son?","unidad":"litros","decimales":0},"solucion":{"valor":18000,"tolerancia":360,"explicacion":"Cada metro cúbico son 1.000 litros: 18 × 1.000 = 18.000 litros."}},{"slug":"tronco-2.s1.p7.v3","orden":7,"grupo":"tronco-2.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La factura del agua de una casa marca 7,5 m³ en el mes. ¿Cuántos litros son?","unidad":"litros","decimales":0},"solucion":{"valor":7500,"tolerancia":150,"explicacion":"Cada metro cúbico son 1.000 litros: 7,5 × 1.000 = 7.500 litros."}},{"slug":"tronco-2.s1.p7.v4","orden":7,"grupo":"tronco-2.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La factura del agua de una casa marca 25 m³ en el mes. ¿Cuántos litros son?","unidad":"litros","decimales":0},"solucion":{"valor":25000,"tolerancia":500,"explicacion":"Cada metro cúbico son 1.000 litros: 25 × 1.000 = 25.000 litros."}},{"slug":"tronco-2.s1.p8","orden":8,"grupo":"tronco-2.s1.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená de menor a mayor.","items":[{"id":"i1","texto":"1 mililitro"},{"id":"i2","texto":"1 litro"},{"id":"i3","texto":"1 metro cúbico"},{"id":"i4","texto":"1 millón de litros"}],"extremos":["Menor","Mayor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada salto es por mil: mil mililitros hacen un litro, mil litros un metro cúbico, y mil metros cúbicos un millón de litros."}},{"slug":"tronco-2.s1.p9","orden":9,"grupo":"tronco-2.s1.p9","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"3,5 kilos es lo mismo que 3.500 gramos.","razones":[{"id":"r1","texto":"Porque kilo multiplica por mil"},{"id":"r2","texto":"Porque kilo multiplica por cien"},{"id":"r3","texto":"Porque gramos y kilos son lo mismo"}]},"solucion":{"valor":true,"explicacion":"Un kilo son mil gramos, así que 3,5 × 1.000 = 3.500 gramos. La coma decimal corre tres lugares.","clave":["r1"]}},{"slug":"tronco-2.s1.p10","orden":10,"grupo":"tronco-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio junta 2.400 kilos de papel para reciclar en un año. ¿Cuántas toneladas son?","unidad":"toneladas","decimales":2},"solucion":{"valor":2.4,"tolerancia":0.048,"explicacion":"Una tonelada son 1.000 kilos: 2.400 ÷ 1.000 = 2,4 toneladas."}},{"slug":"tronco-2.s1.p10.v2","orden":10,"grupo":"tronco-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio junta 850 kilos de papel para reciclar en un año. ¿Cuántas toneladas son?","unidad":"toneladas","decimales":2},"solucion":{"valor":0.85,"tolerancia":0.017,"explicacion":"Una tonelada son 1.000 kilos: 850 ÷ 1.000 = 0,85 toneladas."}},{"slug":"tronco-2.s1.p10.v3","orden":10,"grupo":"tronco-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un barrio junta 12.500 kilos de papel para reciclar en un año. ¿Cuántas toneladas son?","unidad":"toneladas","decimales":2},"solucion":{"valor":12.5,"tolerancia":0.25,"explicacion":"Una tonelada son 1.000 kilos: 12.500 ÷ 1.000 = 12,5 toneladas."}},{"slug":"tronco-2.s1.p11","orden":11,"grupo":"tronco-2.s1.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un compañero hizo estas cuentas. Marcá las que están mal.","segmentos":[{"id":"s1","texto":"2 litros son 2.000 mililitros."},{"id":"s2","texto":"5 metros cúbicos son 500 litros."},{"id":"s3","texto":"1,5 toneladas son 1.500 kilos."},{"id":"s4","texto":"300 gramos son 3 kilos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los errores más frecuentes son correr la coma para el lado equivocado o usar 100 en lugar de 1.000.","por_opcion":{"s2":"Un metro cúbico son 1.000 litros: 5 m³ son 5.000 litros.","s4":"Hay que dividir por mil: 300 g son 0,3 kg."}}},{"slug":"tronco-2.s1.p12","orden":12,"grupo":"tronco-2.s1.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un informe dice que una ciudad \"consume 450 de agua por día\". ¿Qué le falta al dato?","opciones":[{"id":"o1","texto":"La unidad: pueden ser litros, metros cúbicos o millones"},{"id":"o2","texto":"Nada, el número alcanza para entenderlo y compararlo"},{"id":"o3","texto":"El año exacto en que se hizo la medición"},{"id":"o4","texto":"La cantidad de habitantes del país entero"}]},"solucion":{"clave":["o1"],"explicacion":"Sin unidad, 450 puede ser un consumo razonable por persona o un número gigante para toda la ciudad. Pedir la unidad es la primera pregunta frente a cualquier dato.","por_opcion":{"o3":"El año importa, pero antes que eso falta saber qué se está midiendo."}}}]},{"slug":"tronco-2.s2","orden":2,"tipo":"leccion","titulo_es":"Potencia y energía: kW y kWh","bajada_es":"La diferencia que confunde a casi todos, y la cuenta que explica tu factura de luz.","minutos":10,"pasos":[{"slug":"tronco-2.s2.p1","orden":1,"grupo":"tronco-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Potencia es qué tan rápido, energía es cuánto","cuerpo":["La potencia dice cuánta energía usa un aparato en cada instante. Se mide en vatios (W) o kilovatios (kW). Una lamparita LED puede tener 9 W; una estufa eléctrica, 2.000 W.","La energía es la potencia multiplicada por el tiempo que el aparato está prendido. Se mide en vatios hora (Wh) o kilovatios hora (kWh), y es lo que cobra la factura de luz. Un aparato potente prendido un minuto puede gastar menos que uno débil prendido todo el día."],"destacado":{"valor":"kWh = kW × h","texto":"energía = potencia × horas de uso. Es la única cuenta que necesitás para leer la factura."}},"solucion":{}},{"slug":"tronco-2.s2.p2","orden":2,"grupo":"tronco-2.s2.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué mide la factura de electricidad de tu casa?","opciones":[{"id":"o1","texto":"La energía consumida, en kilovatios hora (kWh)"},{"id":"o2","texto":"La potencia de los aparatos, en kilovatios (kW)"},{"id":"o3","texto":"La cantidad de aparatos enchufados en la casa"},{"id":"o4","texto":"El voltaje de la red eléctrica del barrio"}]},"solucion":{"clave":["o1"],"explicacion":"La factura suma cuánta energía pasó por el medidor en el período. Por eso importa tanto cuántas horas está prendido cada aparato.","por_opcion":{"o2":"La potencia contratada puede aparecer, pero lo que se consume y se paga es energía: kWh."}}},{"slug":"tronco-2.s2.p3","orden":3,"grupo":"tronco-2.s2.p3","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una potencia o una energía?","grupos":[{"id":"g1","nombre":"Potencia (W o kW)"},{"id":"g2","nombre":"Energía (Wh o kWh)"}],"items":[{"id":"i1","texto":"9 W"},{"id":"i2","texto":"250 kWh"},{"id":"i3","texto":"2 kW"},{"id":"i4","texto":"30 Wh"},{"id":"i5","texto":"1.500 W"},{"id":"i6","texto":"1,2 kWh"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La \"h\" de hora delata a la energía: vatios hora, kilovatios hora. Sin la h, es potencia."}},{"slug":"tronco-2.s2.p4","orden":4,"grupo":"tronco-2.s2.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Cuánto gasta una estufa","planteo":"Una estufa eléctrica de 2.000 W está prendida 3 horas. ¿Cuánta energía consume?","pasos":["Pasamos la potencia a kilovatios: 2.000 W ÷ 1.000 = 2 kW.","Multiplicamos por las horas: 2 kW × 3 h = 6 kWh."],"resultado":"La estufa consume 6 kWh en esas tres horas. Siempre conviene pasar a kW antes de multiplicar, así el resultado queda directo en kWh."},"solucion":{}},{"slug":"tronco-2.s2.p5","orden":5,"grupo":"tronco-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.500 W está prendido 2 horas. ¿Cuántos kWh consume?","unidad":"kWh","decimales":2},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"Primero a kilovatios: 1.500 W son 1,5 kW. Después por las horas: 1,5 kW × 2 h = 3 kWh."}},{"slug":"tronco-2.s2.p5.v2","orden":5,"grupo":"tronco-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 1.000 W está prendido 4 horas. ¿Cuántos kWh consume?","unidad":"kWh","decimales":2},"solucion":{"valor":4,"tolerancia":0.08,"explicacion":"Primero a kilovatios: 1.000 W son 1 kW. Después por las horas: 1 kW × 4 h = 4 kWh."}},{"slug":"tronco-2.s2.p5.v3","orden":5,"grupo":"tronco-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 2.500 W está prendido 1,5 horas. ¿Cuántos kWh consume?","unidad":"kWh","decimales":2},"solucion":{"valor":3.75,"tolerancia":0.075,"explicacion":"Primero a kilovatios: 2.500 W son 2,5 kW. Después por las horas: 2,5 kW × 1,5 h = 3,75 kWh."}},{"slug":"tronco-2.s2.p5.v4","orden":5,"grupo":"tronco-2.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un aparato de 800 W está prendido 5 horas. ¿Cuántos kWh consume?","unidad":"kWh","decimales":2},"solucion":{"valor":4,"tolerancia":0.08,"explicacion":"Primero a kilovatios: 800 W son 0,8 kW. Después por las horas: 0,8 kW × 5 h = 4 kWh."}},{"slug":"tronco-2.s2.p6","orden":6,"grupo":"tronco-2.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara LED de 9 W está prendida 5 horas por día. ¿Cuántos kWh consume en un mes de 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":1.35,"tolerancia":0.027000000000000003,"explicacion":"Por día: 9 W × 5 h = 45 Wh. En 30 días: 45 × 30 = 1.350 Wh, que son 1,35 kWh."}},{"slug":"tronco-2.s2.p6.v2","orden":6,"grupo":"tronco-2.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara LED de 12 W está prendida 6 horas por día. ¿Cuántos kWh consume en un mes de 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":2.16,"tolerancia":0.0432,"explicacion":"Por día: 12 W × 6 h = 72 Wh. En 30 días: 72 × 30 = 2.160 Wh, que son 2,16 kWh."}},{"slug":"tronco-2.s2.p6.v3","orden":6,"grupo":"tronco-2.s2.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una lámpara LED de 10 W está prendida 4 horas por día. ¿Cuántos kWh consume en un mes de 30 días?","unidad":"kWh","decimales":2},"solucion":{"valor":1.2,"tolerancia":0.024,"explicacion":"Por día: 10 W × 4 h = 40 Wh. En 30 días: 40 × 30 = 1.200 Wh, que son 1,2 kWh."}},{"slug":"tronco-2.s2.p7","orden":7,"grupo":"tronco-2.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que está prendido todo el día","cuerpo":["Como la energía es potencia por tiempo, los aparatos que nunca se apagan pesan aunque tengan poca potencia. La heladera funciona las 24 horas del día; un router, también. Un cargador enchufado sin teléfono consume muy poco, pero todo el año.","Al revés, un secador de pelo de alta potencia usado cinco minutos gasta poco en total. Para saber qué pesa en la factura hay que mirar las dos cosas a la vez: potencia y horas."]},"solucion":{}},{"slug":"tronco-2.s2.p8","orden":8,"grupo":"tronco-2.s2.p8","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos usos según la energía que consumen en un día, de mayor a menor.","items":[{"id":"i1","texto":"Estufa de 2.000 W, 4 horas"},{"id":"i2","texto":"Heladera de 100 W de promedio, 24 horas"},{"id":"i3","texto":"Router de 10 W, 24 horas"},{"id":"i4","texto":"Secador de 1.800 W, 5 minutos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El secador es el más potente de la lista y el que menos energía usa en el día: se prende cinco minutos. La potencia sola no alcanza para comparar.","valores":{"i1":"8 kWh","i2":"2,4 kWh","i3":"0,24 kWh","i4":"0,15 kWh"}}},{"slug":"tronco-2.s2.p9","orden":9,"grupo":"tronco-2.s2.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un aparato de mucha potencia siempre gasta más energía que uno de poca potencia.","razones":[{"id":"r1","texto":"Porque la energía depende también de cuánto tiempo está prendido"},{"id":"r2","texto":"Porque la potencia no tiene relación con la energía"},{"id":"r3","texto":"Porque los aparatos potentes usan otra electricidad"}]},"solucion":{"valor":false,"explicacion":"Depende del tiempo. Un secador de 1.800 W usado cinco minutos consume 0,15 kWh; un router de 10 W prendido todo el día consume 0,24 kWh. Energía = potencia × tiempo.","clave":["r1"]}},{"slug":"tronco-2.s2.p10","orden":10,"grupo":"tronco-2.s2.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos necesitás para calcular cuánta energía consume un aparato por mes? Marcá todos.","opciones":[{"id":"o1","texto":"Su potencia"},{"id":"o2","texto":"Cuántas horas por día está prendido"},{"id":"o3","texto":"Cuántos días del mes se usa"},{"id":"o4","texto":"El color del aparato"},{"id":"o5","texto":"La marca del enchufe"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Potencia × horas por día × días: con esas tres cosas se estima el consumo de cualquier aparato."}},{"slug":"tronco-2.s2.p11","orden":11,"grupo":"tronco-2.s2.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar consumió 210 kWh en el mes. Si cada kWh costara $60, ¿cuánto sería la parte de energía de la factura, en pesos?","unidad":"pesos","decimales":0},"solucion":{"valor":12600,"tolerancia":252,"explicacion":"210 kWh × $60 por kWh = $12.600. El precio por kWh es un ejemplo: la tarifa real depende de la zona y del tipo de usuario."}},{"slug":"tronco-2.s2.p11.v2","orden":11,"grupo":"tronco-2.s2.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar consumió 340 kWh en el mes. Si cada kWh costara $45, ¿cuánto sería la parte de energía de la factura, en pesos?","unidad":"pesos","decimales":0},"solucion":{"valor":15300,"tolerancia":306,"explicacion":"340 kWh × $45 por kWh = $15.300. El precio por kWh es un ejemplo: la tarifa real depende de la zona y del tipo de usuario."}},{"slug":"tronco-2.s2.p11.v3","orden":11,"grupo":"tronco-2.s2.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un hogar consumió 165 kWh en el mes. Si cada kWh costara $80, ¿cuánto sería la parte de energía de la factura, en pesos?","unidad":"pesos","decimales":0},"solucion":{"valor":13200,"tolerancia":264,"explicacion":"165 kWh × $80 por kWh = $13.200. El precio por kWh es un ejemplo: la tarifa real depende de la zona y del tipo de usuario."}},{"slug":"tronco-2.s2.p12","orden":12,"grupo":"tronco-2.s2.p12","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Florencia apaga la luz de un pasillo (LED de 9 W) que quedaba prendida toda la noche, 10 horas. ¿Cuánto ahorra por noche?","opciones":[{"id":"o1","texto":"90 Wh, o sea 0,09 kWh"},{"id":"o2","texto":"9 kWh por noche"},{"id":"o3","texto":"90 kWh por noche"},{"id":"o4","texto":"Nada, las lámparas LED no consumen"}]},"solucion":{"clave":["o1"],"explicacion":"9 W × 10 h = 90 Wh = 0,09 kWh. Es poco por noche, pero en un año son unos 33 kWh. Los ahorros chicos se vuelven visibles cuando se multiplican por el tiempo.","por_opcion":{"o3":"Cuidado con la unidad: 9 W × 10 h son 90 Wh. Para kWh hay que dividir por mil."}}}]},{"slug":"tronco-2.s3","orden":3,"tipo":"leccion","titulo_es":"El CO₂ equivalente","bajada_es":"Por qué el metano pesa más que el CO₂, y cómo se suman gases distintos en un solo número.","minutos":11,"pasos":[{"slug":"tronco-2.s3.p1","orden":1,"grupo":"tronco-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Gases que abrigan","cuerpo":["Algunos gases de la atmósfera dejan pasar la luz del sol pero retienen parte del calor que la Tierra devuelve. Sin ellos, el planeta sería helado; con demasiados, se calienta. Los principales son el dióxido de carbono (CO₂), el metano (CH₄) y el óxido nitroso (N₂O).","El CO₂ sale sobre todo de quemar combustibles fósiles y de la deforestación. El metano, del ganado, los rellenos sanitarios, los arrozales y las pérdidas de gas. El óxido nitroso, principalmente de los fertilizantes."]},"solucion":{}},{"slug":"tronco-2.s3.p2","orden":2,"grupo":"tronco-2.s3.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada gas con una de sus fuentes principales.","izquierda":[{"id":"a1","texto":"Dióxido de carbono (CO₂)"},{"id":"a2","texto":"Metano (CH₄)"},{"id":"a3","texto":"Óxido nitroso (N₂O)"}],"derecha":[{"id":"b1","texto":"Quemar nafta, gas o carbón"},{"id":"b2","texto":"La digestión del ganado y los rellenos sanitarios"},{"id":"b3","texto":"Los fertilizantes nitrogenados"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Cada gas tiene sus fuentes, y por eso las soluciones también son distintas: no se reduce el metano de un relleno cambiando de auto."}},{"slug":"tronco-2.s3.p3","orden":3,"grupo":"tronco-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No todos calientan igual","cuerpo":["Un kilo de metano atrapa mucho más calor que un kilo de CO₂, aunque dura menos años en la atmósfera. Para compararlos, se usa el potencial de calentamiento global: cuánto calienta un gas respecto del CO₂ en un período, normalmente 100 años.","Con ese criterio, el metano calienta alrededor de 28 veces más que el CO₂ (el IPCC lo estima entre 27 y 30 según su origen), y el óxido nitroso unas 270 veces más. El CO₂ vale 1 por definición."],"destacado":{"valor":"≈ 28×","texto":"un kilo de metano calienta, en 100 años, lo que unos 28 kilos de CO₂."}},"solucion":{}},{"slug":"tronco-2.s3.p4","orden":4,"grupo":"tronco-2.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Sumar todo en una sola cuenta","cuerpo":["Para sumar gases distintos se pasan todos a \"CO₂ equivalente\" (CO₂e): se multiplica la masa de cada gas por su potencial. Así, 1 kilo de metano cuenta como unos 28 kg de CO₂e.","Cuando leas \"la huella de este alimento es de 3 kg CO₂e\", significa que todos los gases que emitió producirlo, juntos, calientan lo mismo que 3 kg de CO₂."]},"solucion":{}},{"slug":"tronco-2.s3.p5","orden":5,"grupo":"tronco-2.s3.p5","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Pasar metano a CO₂e","planteo":"Un relleno sanitario emite 2 toneladas de metano. ¿Cuánto es en CO₂ equivalente, usando un potencial de 28?","pasos":["CO₂e = masa del gas × potencial de calentamiento.","2 t × 28 = 56 t CO₂e."],"resultado":"Esas 2 toneladas de metano calientan como 56 toneladas de CO₂. Por eso evitar que los restos de comida terminen enterrados rinde tanto."},"solucion":{}},{"slug":"tronco-2.s3.p6","orden":6,"grupo":"tronco-2.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se emiten 5 kg de metano, ¿cuántos kg de CO₂e son? (Usá un potencial de 28.)","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"5 kg × 28 = 140 kg CO₂e. El metano cuenta 28 veces lo que el CO₂ en un horizonte de 100 años."}},{"slug":"tronco-2.s3.p6.v2","orden":6,"grupo":"tronco-2.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se emiten 12 kg de metano, ¿cuántos kg de CO₂e son? (Usá un potencial de 28.)","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":336,"tolerancia":6.72,"explicacion":"12 kg × 28 = 336 kg CO₂e. El metano cuenta 28 veces lo que el CO₂ en un horizonte de 100 años."}},{"slug":"tronco-2.s3.p6.v3","orden":6,"grupo":"tronco-2.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se emiten 3 kg de metano, ¿cuántos kg de CO₂e son? (Usá un potencial de 28.)","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":84,"tolerancia":1.68,"explicacion":"3 kg × 28 = 84 kg CO₂e. El metano cuenta 28 veces lo que el CO₂ en un horizonte de 100 años."}},{"slug":"tronco-2.s3.p6.v4","orden":6,"grupo":"tronco-2.s3.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se emiten 40 kg de metano, ¿cuántos kg de CO₂e son? (Usá un potencial de 28.)","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":1120,"tolerancia":22.400000000000002,"explicacion":"40 kg × 28 = 1.120 kg CO₂e. El metano cuenta 28 veces lo que el CO₂ en un horizonte de 100 años."}},{"slug":"tronco-2.s3.p7","orden":7,"grupo":"tronco-2.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el metano dura menos años en la atmósfera que el CO₂, calienta menos.","razones":[{"id":"r1","texto":"Porque atrapa mucho más calor por kilo, aunque dure menos"},{"id":"r2","texto":"Porque el metano no es un gas de efecto invernadero"},{"id":"r3","texto":"Porque todos los gases calientan exactamente igual"}]},"solucion":{"valor":false,"explicacion":"Dura menos, pero mientras está atrapa muchísimo más calor. Medido a 100 años, un kilo de metano calienta unas 28 veces más que uno de CO₂; a 20 años, la diferencia es todavía mayor.","clave":["r1"]}},{"slug":"tronco-2.s3.p8","orden":8,"grupo":"tronco-2.s3.p8","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená por cuánto calienta un kilo de cada gas en 100 años, de más a menos.","items":[{"id":"i1","texto":"Óxido nitroso (N₂O)"},{"id":"i2","texto":"Metano (CH₄)"},{"id":"i3","texto":"Dióxido de carbono (CO₂)"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"El CO₂ calienta menos por kilo, pero se emite en cantidades enormes y dura siglos: por eso sigue siendo el gas que más aporta al calentamiento total.","valores":{"i1":"≈ 270 veces el CO₂","i2":"≈ 28 veces el CO₂","i3":"1, por definición"}}},{"slug":"tronco-2.s3.p9","orden":9,"grupo":"tronco-2.s3.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si el CO₂ calienta menos por kilo que el metano, ¿por qué es el gas que más contribuye al calentamiento?","opciones":[{"id":"o1","texto":"Porque se emite en cantidades enormes y dura siglos en el aire"},{"id":"o2","texto":"Porque es el único gas que retiene calor en la atmósfera"},{"id":"o3","texto":"Porque el metano no llega a la atmósfera, se queda en el suelo"},{"id":"o4","texto":"Porque el CO₂ se mide en otra unidad que agranda los números"}]},"solucion":{"clave":["o1"],"explicacion":"Importa la potencia por kilo y también la cantidad y la duración. El CO₂ gana en las dos últimas.","por_opcion":{"o3":"El metano sí llega a la atmósfera: sale de rellenos, ganado y pérdidas de gas."}}},{"slug":"tronco-2.s3.p10","orden":10,"grupo":"tronco-2.s3.p10","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una actividad emite 100 kg de CO₂ y 2 kg de metano. ¿Cuál es su huella total en kg CO₂e? (Metano = 28.)","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":156,"tolerancia":3.12,"explicacion":"CO₂: 100 kg × 1 = 100. Metano: 2 kg × 28 = 56. Total: 100 + 56 = 156 kg CO₂e."}},{"slug":"tronco-2.s3.p10.v2","orden":10,"grupo":"tronco-2.s3.p10","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una actividad emite 250 kg de CO₂ y 5 kg de metano. ¿Cuál es su huella total en kg CO₂e? (Metano = 28.)","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":390,"tolerancia":7.8,"explicacion":"CO₂: 250 kg × 1 = 250. Metano: 5 kg × 28 = 140. Total: 250 + 140 = 390 kg CO₂e."}},{"slug":"tronco-2.s3.p10.v3","orden":10,"grupo":"tronco-2.s3.p10","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una actividad emite 60 kg de CO₂ y 1 kg de metano. ¿Cuál es su huella total en kg CO₂e? (Metano = 28.)","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":88,"tolerancia":1.76,"explicacion":"CO₂: 60 kg × 1 = 60. Metano: 1 kg × 28 = 28. Total: 60 + 28 = 88 kg CO₂e."}},{"slug":"tronco-2.s3.p11","orden":11,"grupo":"tronco-2.s3.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para sumar gases distintos se pasan todos a {{0}}, multiplicando la {{1}} de cada gas por su {{2}} de calentamiento.","banco":[{"id":"w1","texto":"CO₂ equivalente"},{"id":"w2","texto":"masa"},{"id":"w3","texto":"potencial"},{"id":"w4","texto":"volumen"},{"id":"w5","texto":"oxígeno"},{"id":"w6","texto":"temperatura"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Masa × potencial = CO₂e. Es la unidad común de todas las huellas de carbono que vas a ver en el árbol."}},{"slug":"tronco-2.s3.p12","orden":12,"grupo":"tronco-2.s3.p12","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta etiqueta de un producto y marcá lo que no tiene sentido.","segmentos":[{"id":"s1","texto":"Huella de carbono: 2,1 kg CO₂e por unidad."},{"id":"s2","texto":"Incluye las emisiones de metano del proceso,"},{"id":"s3","texto":"medidas en litros de CO₂e."},{"id":"s4","texto":"El metano se contó como si calentara igual que el CO₂."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Una huella bien hecha usa unidades de masa y aplica el potencial de cada gas.","por_opcion":{"s3":"El CO₂e se expresa en masa (gramos, kilos, toneladas), no en litros.","s4":"Si se cuenta así, se subestima: el metano pesa unas 28 veces más."}}},{"slug":"tronco-2.s3.p13","orden":13,"grupo":"tronco-2.s3.p13","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué gas sale principalmente de cada fuente?","grupos":[{"id":"g1","nombre":"Sobre todo CO₂"},{"id":"g2","nombre":"Sobre todo metano"}],"items":[{"id":"i1","texto":"El caño de escape de un auto a nafta"},{"id":"i2","texto":"Un relleno sanitario con restos de comida"},{"id":"i3","texto":"Una caldera a gas"},{"id":"i4","texto":"Un campo con ganado vacuno"},{"id":"i5","texto":"Un bosque que se quema"},{"id":"i6","texto":"Una pérdida en un gasoducto"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El gas natural es casi todo metano: si se quema, sale CO₂; si se escapa sin quemar, sale metano, que calienta mucho más."}}]},{"slug":"tronco-2.s4","orden":4,"tipo":"leccion","titulo_es":"Leer un número ambiental","bajada_es":"Total, por persona, por año, por kilo: el mismo dato cambia de significado según cómo se mira.","minutos":11,"pasos":[{"slug":"tronco-2.s4.p1","orden":1,"grupo":"tronco-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Total o por persona","cuerpo":["Un país grande puede emitir mucho CO₂ en total simplemente porque tiene mucha gente. Otro, más chico, puede emitir poco en total y muchísimo por habitante. Los dos números son verdaderos, pero responden preguntas distintas.","El total sirve para ver qué pesa en el planeta. El valor por persona sirve para comparar formas de vivir. Cuando leas un ranking, fijate primero cuál de los dos está usando."]},"solucion":{}},{"slug":"tronco-2.s4.p2","orden":2,"grupo":"tronco-2.s4.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Dos países","planteo":"El país A emite 600 millones de toneladas de CO₂ por año y tiene 200 millones de habitantes. El país B emite 60 millones de toneladas y tiene 5 millones de habitantes.","pasos":["A por persona: 600 ÷ 200 = 3 toneladas por habitante.","B por persona: 60 ÷ 5 = 12 toneladas por habitante."],"resultado":"A emite diez veces más en total, pero cada habitante de B emite cuatro veces más que uno de A. Las dos lecturas son correctas."},"solucion":{}},{"slug":"tronco-2.s4.p3","orden":3,"grupo":"tronco-2.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 400 millones de toneladas de CO₂e por año y tiene 50 millones de habitantes. ¿Cuántas toneladas emite por persona?","unidad":"t por persona","decimales":1},"solucion":{"valor":8,"tolerancia":0.16,"explicacion":"Se dividen las dos cifras, que están en millones: 400 ÷ 50 = 8 toneladas por habitante por año."}},{"slug":"tronco-2.s4.p3.v2","orden":3,"grupo":"tronco-2.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 90 millones de toneladas de CO₂e por año y tiene 10 millones de habitantes. ¿Cuántas toneladas emite por persona?","unidad":"t por persona","decimales":1},"solucion":{"valor":9,"tolerancia":0.18,"explicacion":"Se dividen las dos cifras, que están en millones: 90 ÷ 10 = 9 toneladas por habitante por año."}},{"slug":"tronco-2.s4.p3.v3","orden":3,"grupo":"tronco-2.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 1.200 millones de toneladas de CO₂e por año y tiene 400 millones de habitantes. ¿Cuántas toneladas emite por persona?","unidad":"t por persona","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"Se dividen las dos cifras, que están en millones: 1.200 ÷ 400 = 3 toneladas por habitante por año."}},{"slug":"tronco-2.s4.p3.v4","orden":3,"grupo":"tronco-2.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 30 millones de toneladas de CO₂e por año y tiene 2 millones de habitantes. ¿Cuántas toneladas emite por persona?","unidad":"t por persona","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"Se dividen las dos cifras, que están en millones: 30 ÷ 2 = 15 toneladas por habitante por año."}},{"slug":"tronco-2.s4.p4","orden":4,"grupo":"tronco-2.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Siempre hay un \"por\"","cuerpo":["Casi todos los datos ambientales tienen un denominador escondido: por año, por día, por persona, por kilo de producto, por kilómetro recorrido. \"Esta carne emite 60 kg CO₂e\" no dice nada si no sabés si es por kilo, por plato o por vaca.","Antes de comparar dos números, asegurate de que tengan el mismo \"por\". Comparar litros por día con litros por mes es comparar manzanas con peras."],"lista":["kg CO₂e por kilo de alimento","litros por persona por día","gramos de CO₂ por kilómetro","kWh por mes"]},"solucion":{}},{"slug":"tronco-2.s4.p5","orden":5,"grupo":"tronco-2.s4.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un titular dice: \"Los autos eléctricos emiten 0 g de CO₂\". ¿Qué falta aclarar?","opciones":[{"id":"o1","texto":"Que es solo el caño de escape: fabricarlo y la electricidad emiten"},{"id":"o2","texto":"Nada, un auto eléctrico no emite nada en toda su vida útil"},{"id":"o3","texto":"Cuántos autos eléctricos hay circulando hoy en el país"},{"id":"o4","texto":"El precio del auto eléctrico comparado con uno a nafta"}]},"solucion":{"clave":["o1"],"explicacion":"El \"por\" acá es \"por kilómetro, en el caño de escape\". Un análisis completo mira la fabricación, la batería y de dónde sale la electricidad. Lo verás en Movilidad.","por_opcion":{"o3":"Ese es otro dato: acá lo que falta es qué parte de la vida del auto se está midiendo."}}},{"slug":"tronco-2.s4.p6","orden":6,"grupo":"tronco-2.s4.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un total o un valor relativo (por algo)?","grupos":[{"id":"g1","nombre":"Total"},{"id":"g2","nombre":"Relativo (por algo)"}],"items":[{"id":"i1","texto":"Una ciudad junta 3.000 toneladas de basura por día"},{"id":"i2","texto":"Cada vecino genera 1,2 kg de basura por día"},{"id":"i3","texto":"Un país emitió 380 millones de toneladas de CO₂e en un año"},{"id":"i4","texto":"Un auto emite 120 g de CO₂ por kilómetro"},{"id":"i5","texto":"Una ducha usa 10 litros por minuto"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Los totales dicen cuánto pesa algo en el conjunto; los relativos permiten comparar entre casos de distinto tamaño."}},{"slug":"tronco-2.s4.p7","orden":7,"grupo":"tronco-2.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Porcentajes: siempre ¿de qué?","cuerpo":["Un porcentaje es una parte de un total. \"El 40 % de la basura es comida\" dice qué parte ocupa la comida dentro de la basura, pero no cuánta basura hay.","Y ojo con los aumentos: si algo pasa de 10 a 15, subió 5 unidades, que es un 50 %. Si pasa de 100 a 105, subió también 5, pero es un 5 %. El mismo cambio absoluto puede ser un porcentaje grande o chico según de dónde parte."]},"solucion":{}},{"slug":"tronco-2.s4.p8","orden":8,"grupo":"tronco-2.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una escuela genera 2.000 kg de residuos por año y el 45 % son restos orgánicos. ¿Cuántos kilos de orgánicos son?","unidad":"kg","decimales":0},"solucion":{"valor":900,"tolerancia":18,"explicacion":"Un porcentaje es una parte de cien: 45 % de 2.000 = 2.000 × 45 ÷ 100 = 900 kg de orgánicos."}},{"slug":"tronco-2.s4.p8.v2","orden":8,"grupo":"tronco-2.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una escuela genera 800 kg de residuos por año y el 30 % son restos orgánicos. ¿Cuántos kilos de orgánicos son?","unidad":"kg","decimales":0},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"Un porcentaje es una parte de cien: 30 % de 800 = 800 × 30 ÷ 100 = 240 kg de orgánicos."}},{"slug":"tronco-2.s4.p8.v3","orden":8,"grupo":"tronco-2.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una escuela genera 1.500 kg de residuos por año y el 20 % son restos orgánicos. ¿Cuántos kilos de orgánicos son?","unidad":"kg","decimales":0},"solucion":{"valor":300,"tolerancia":6,"explicacion":"Un porcentaje es una parte de cien: 20 % de 1.500 = 1.500 × 20 ÷ 100 = 300 kg de orgánicos."}},{"slug":"tronco-2.s4.p8.v4","orden":8,"grupo":"tronco-2.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una escuela genera 360 kg de residuos por año y el 25 % son restos orgánicos. ¿Cuántos kilos de orgánicos son?","unidad":"kg","decimales":0},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"Un porcentaje es una parte de cien: 25 % de 360 = 360 × 25 ÷ 100 = 90 kg de orgánicos."}},{"slug":"tronco-2.s4.p9","orden":9,"grupo":"tronco-2.s4.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El consumo de agua de un club pasó de 80 m³ a 100 m³ por mes. ¿En qué porcentaje aumentó?","unidad":"%","decimales":1},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"Aumento: 100 − 80 = 20 m³. Porcentaje: 20 ÷ 80 × 100 = 25 %. Siempre se divide por el valor de partida."}},{"slug":"tronco-2.s4.p9.v2","orden":9,"grupo":"tronco-2.s4.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El consumo de agua de un club pasó de 200 m³ a 230 m³ por mes. ¿En qué porcentaje aumentó?","unidad":"%","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"Aumento: 230 − 200 = 30 m³. Porcentaje: 30 ÷ 200 × 100 = 15 %. Siempre se divide por el valor de partida."}},{"slug":"tronco-2.s4.p9.v3","orden":9,"grupo":"tronco-2.s4.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El consumo de agua de un club pasó de 50 m³ a 75 m³ por mes. ¿En qué porcentaje aumentó?","unidad":"%","decimales":1},"solucion":{"valor":50,"tolerancia":1,"explicacion":"Aumento: 75 − 50 = 25 m³. Porcentaje: 25 ÷ 50 × 100 = 50 %. Siempre se divide por el valor de partida."}},{"slug":"tronco-2.s4.p10","orden":10,"grupo":"tronco-2.s4.p10","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué preguntas conviene hacerle a cualquier número ambiental? Marcá todas las útiles.","opciones":[{"id":"o1","texto":"¿En qué unidad está?"},{"id":"o2","texto":"¿Es un total o es por persona, por año o por kilo?"},{"id":"o3","texto":"¿De qué total es este porcentaje?"},{"id":"o4","texto":"¿Quién lo midió y cómo?"},{"id":"o5","texto":"¿Es un número redondo o tiene decimales?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Unidad, denominador, total de referencia y fuente: con esas cuatro preguntas se desarma la mayoría de los datos confusos."}},{"slug":"tronco-2.s4.p11","orden":11,"grupo":"tronco-2.s4.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un país emite mucho CO₂ en total, cada uno de sus habitantes también emite mucho.","razones":[{"id":"r1","texto":"Porque el total depende de cuánta gente hay, no solo de cuánto emite cada persona"},{"id":"r2","texto":"Porque los totales y los valores por persona siempre coinciden"},{"id":"r3","texto":"Porque la población no se puede medir"}]},"solucion":{"valor":false,"explicacion":"No necesariamente. Un país con muchísima gente puede tener un total enorme y un valor por persona bajo; uno chico, al revés. Para hablar de \"cada habitante\" hay que dividir por la población.","clave":["r1"]}},{"slug":"tronco-2.s4.p12","orden":12,"grupo":"tronco-2.s4.p12","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un posteo compara dos ciudades. Marcá los razonamientos engañosos.","segmentos":[{"id":"s1","texto":"La ciudad X tira 5.000 toneladas de basura por día y la ciudad Y, 500."},{"id":"s2","texto":"Entonces cada vecino de X tira diez veces más basura que uno de Y."},{"id":"s3","texto":"La basura de Y subió un 20 % este año,"},{"id":"s4","texto":"así que ahora Y tira más basura que X."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un total no dice nada por persona, y un porcentaje no dice nada sin su base.","por_opcion":{"s2":"Sin saber cuántos habitantes tiene cada ciudad no se puede comparar por vecino.","s4":"Un 20 % sobre 500 son 100 toneladas más: 600, muy lejos de 5.000."}}},{"slug":"tronco-2.s4.p13","orden":13,"grupo":"tronco-2.s4.p13","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada dato con la pregunta que responde mejor.","izquierda":[{"id":"a1","texto":"Toneladas de CO₂e de un país por año"},{"id":"a2","texto":"Toneladas de CO₂e por habitante"},{"id":"a3","texto":"Gramos de CO₂ por kilómetro"},{"id":"a4","texto":"Porcentaje de orgánicos en la basura"}],"derecha":[{"id":"b1","texto":"¿Cuánto pesa ese país en el total del planeta?"},{"id":"b2","texto":"¿Cómo se compara la forma de vivir con otro país?"},{"id":"b3","texto":"¿Qué auto contamina menos al recorrer lo mismo?"},{"id":"b4","texto":"¿Qué parte de la basura se podría compostar?"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada forma de presentar un dato sirve para una pregunta. Elegir la correcta es la mitad del análisis."}}]},{"slug":"tronco-2.s5","orden":5,"tipo":"leccion","titulo_es":"Órdenes de magnitud","bajada_es":"Qué pesa de verdad: la diferencia entre ahorrar gramos y ahorrar toneladas.","minutos":10,"pasos":[{"slug":"tronco-2.s5.p1","orden":1,"grupo":"tronco-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pensar en potencias de diez","cuerpo":["Un orden de magnitud es un factor de diez. 10, 100 y 1.000 están separados por un orden de magnitud cada uno. Cuando dos acciones difieren en uno o dos órdenes de magnitud, no hace falta el número exacto para saber cuál importa más.","Esta es una de las ideas más útiles del árbol entero: a veces nos esforzamos mucho en algo que ahorra gramos y dejamos pasar algo que ahorra toneladas. No porque lo chico esté mal, sino porque el tiempo y la energía de cada persona son limitados."],"destacado":{"valor":"×10","texto":"un orden de magnitud. Entre 1 kg y 1 tonelada hay tres."}},"solucion":{}},{"slug":"tronco-2.s5.p2","orden":2,"grupo":"tronco-2.s5.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estas masas de menor a mayor.","items":[{"id":"i1","texto":"1 gramo"},{"id":"i2","texto":"1 kilo"},{"id":"i3","texto":"1 tonelada"},{"id":"i4","texto":"1.000 toneladas"}],"extremos":["Menor","Mayor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada paso multiplica por mil, o sea, tres órdenes de magnitud. Entre un gramo y mil toneladas hay nueve."}},{"slug":"tronco-2.s5.p3","orden":3,"grupo":"tronco-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una acción ahorra 5 kg de CO₂e por año y otra ahorra 500 kg. ¿Cuántas veces más ahorra la segunda?","unidad":"veces","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"500 ÷ 5 = 100. Son 2 órdenes de magnitud de diferencia."}},{"slug":"tronco-2.s5.p3.v2","orden":3,"grupo":"tronco-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una acción ahorra 20 kg de CO₂e por año y otra ahorra 2.000 kg. ¿Cuántas veces más ahorra la segunda?","unidad":"veces","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"2.000 ÷ 20 = 100. Son 2 órdenes de magnitud de diferencia."}},{"slug":"tronco-2.s5.p3.v3","orden":3,"grupo":"tronco-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una acción ahorra 2 kg de CO₂e por año y otra ahorra 2.000 kg. ¿Cuántas veces más ahorra la segunda?","unidad":"veces","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"2.000 ÷ 2 = 1.000. Son 3 órdenes de magnitud de diferencia."}},{"slug":"tronco-2.s5.p4","orden":4,"grupo":"tronco-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué acciones pesan más","cuerpo":["Un estudio de 2017 (Wynes y Nicholas) comparó cuánto CO₂e ahorran por año distintas acciones personales en países de altos ingresos. Vivir sin auto rondaba 2,4 toneladas por año; evitar un vuelo transatlántico de ida y vuelta, 1,6; una dieta basada en plantas, 0,8. Reciclar, alrededor de 0,2, y cambiar lamparitas, cerca de 0,1.","Los números exactos dependen del país, pero el patrón se repite: transporte, energía del hogar y alimentación pesan órdenes de magnitud más que muchos gestos chicos. Y los gestos chicos siguen sumando: son buenos puntos de partida."],"datos":{"tipo":"barras","titulo":"Ahorro estimado por persona y por año (países de altos ingresos)","unidad":"t CO₂e","filas":[{"etiqueta":"Vivir sin auto","valor":2.4},{"etiqueta":"Evitar un vuelo transatlántico ida y vuelta","valor":1.6},{"etiqueta":"Dieta basada en plantas","valor":0.8},{"etiqueta":"Reciclar","valor":0.21},{"etiqueta":"Cambiar lamparitas","valor":0.1}],"nota":"Fuente: Wynes y Nicholas (2017). Valores aproximados; cambian según el país."}},"solucion":{}},{"slug":"tronco-2.s5.p5","orden":5,"grupo":"tronco-2.s5.p5","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según el estudio de la tarjeta anterior, ordená estas acciones por cuánto ahorran por año, de más a menos.","items":[{"id":"i1","texto":"Vivir sin auto"},{"id":"i2","texto":"Dieta basada en plantas"},{"id":"i3","texto":"Reciclar"},{"id":"i4","texto":"Cambiar lamparitas"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Entre la primera y la última hay más de veinte veces de diferencia. Conocer el orden ayuda a elegir por dónde empezar sin culpa y con criterio.","valores":{"i1":"≈ 2,4 t CO₂e","i2":"≈ 0,8 t CO₂e","i3":"≈ 0,2 t CO₂e","i4":"≈ 0,1 t CO₂e"}}},{"slug":"tronco-2.s5.p6","orden":6,"grupo":"tronco-2.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como reciclar ahorra menos que dejar el auto, no tiene sentido reciclar.","razones":[{"id":"r1","texto":"Porque priorizar no es descartar: lo chico también suma"},{"id":"r2","texto":"Porque reciclar ahorra más que no usar el auto"},{"id":"r3","texto":"Porque el CO₂ no es lo único que importa, así que nada se puede comparar"}]},"solucion":{"valor":false,"explicacion":"Pensar en órdenes de magnitud sirve para priorizar, no para descartar. Reciclar sigue ahorrando recursos y energía, es fácil y además cuida otras cosas además del clima. La idea es no quedarse solo en lo chico.","clave":["r1"]}},{"slug":"tronco-2.s5.p7","orden":7,"grupo":"tronco-2.s5.p7","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá: si una familia hace una acción que ahorra 0,1 toneladas por año y otra que ahorra 2 toneladas por año, ¿cuántos años de la primera equivalen a un año de la segunda?","min":1,"max":100,"paso":1,"unidad":"años","escala":"lineal"},"solucion":{"valor":20,"banda":"lineal","explicacion":"2 ÷ 0,1 = 20 años. Hace falta mantener la acción chica veinte años para igualar un solo año de la grande."}},{"slug":"tronco-2.s5.p8","orden":8,"grupo":"tronco-2.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El efecto rebote","cuerpo":["A veces una mejora se come a sí misma. Si una casa pone lamparitas eficientes y, como ahora \"no gastan\", las deja prendidas el doble de tiempo, parte del ahorro se pierde. Si un auto gasta menos por kilómetro y por eso se usa más, pasa lo mismo.","No quiere decir que la eficiencia no sirva: casi siempre ahorra algo. Quiere decir que hay que medir el resultado final y no solo el ahorro prometido."]},"solucion":{}},{"slug":"tronco-2.s5.p9","orden":9,"grupo":"tronco-2.s5.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una familia cambia su auto por uno que gasta la mitad de nafta por kilómetro, y empieza a viajar el doble de kilómetros. ¿Qué pasa con su consumo total de nafta?","opciones":[{"id":"o1","texto":"Queda igual: la mitad por kilómetro, el doble de kilómetros"},{"id":"o2","texto":"Se reduce a la mitad, porque el auto nuevo es más eficiente"},{"id":"o3","texto":"Se duplica, porque viajan el doble"},{"id":"o4","texto":"Baja a cero, porque el auto nuevo es eficiente"}]},"solucion":{"clave":["o1"],"explicacion":"La mitad × el doble = lo mismo. Es un efecto rebote completo: la mejora de eficiencia se usó para viajar más.","por_opcion":{"o3":"El auto gasta la mitad por kilómetro, así que duplicar los kilómetros no duplica el consumo: lo deja igual."}}},{"slug":"tronco-2.s5.p10","orden":10,"grupo":"tronco-2.s5.p10","tipo":"cadena","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un efecto rebote.","items":[{"id":"i1","texto":"Una familia instala un aire acondicionado más eficiente"},{"id":"i2","texto":"Cada hora de uso cuesta menos"},{"id":"i3","texto":"Lo prenden más horas y a menor temperatura"},{"id":"i4","texto":"El ahorro de energía es menor al esperado"},{"id":"i5","texto":"El aparato nuevo consume más por hora que el viejo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El señuelo contradice el punto de partida: el aparato nuevo es más eficiente. El rebote viene del cambio de uso, no del aparato."}},{"slug":"tronco-2.s5.p11","orden":11,"grupo":"tronco-2.s5.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este razonamiento y marcá lo que está mal pensado.","segmentos":[{"id":"s1","texto":"Desenchufé el cargador del celular, que consume casi nada en espera,"},{"id":"s2","texto":"así que ya hice mi parte por el clima y puedo viajar en avión las veces que quiera."},{"id":"s3","texto":"Igual, lo que conviene es sumar gestos y también mirar lo que pesa más."}]},"solucion":{"clave":["s2"],"explicacion":"Los gestos chicos no compensan los grandes: están en distintos órdenes de magnitud. Lo sano es sumar los dos, sin culpa y con números.","por_opcion":{"s2":"Desenchufar un cargador ahorra gramos; un vuelo largo emite cientos de kilos o más. No se compensan."}}},{"slug":"tronco-2.s5.p12","orden":12,"grupo":"tronco-2.s5.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Entre 1 kilo y 1 tonelada hay {{0}} órdenes de magnitud, porque una tonelada son {{1}} kilos.","banco":[{"id":"w1","texto":"tres"},{"id":"w2","texto":"mil"},{"id":"w3","texto":"dos"},{"id":"w4","texto":"cien"},{"id":"w5","texto":"diez mil"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Cada orden de magnitud es un factor de diez: 10 × 10 × 10 = 1.000, o sea tres órdenes."}}]},{"slug":"tronco-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: medir para entender","bajada_es":"Unidades, energía, CO₂e y órdenes de magnitud, todo mezclado.","minutos":8,"pasos":[{"slug":"tronco-2.s6.p1","orden":1,"grupo":"tronco-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Medir para entender». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"tronco-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la cuenta de la casa de Tomi","bajada_es":"Un caso con números reales de una casa. Aprobalo para completar la unidad.","minutos":10,"pasos":[{"slug":"tronco-2.s7.p1","orden":1,"grupo":"tronco-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["Tomi vive con su familia de cuatro personas y quiere saber por dónde empezar a cuidar el ambiente en casa. Juntó algunos datos: la factura de luz dice 300 kWh en el mes; la de agua, 18 m³; en casa tiran unos 5 kilos de basura por día.","También averiguó que en su zona cada kWh de la red emite, en promedio, unos 0,4 kg de CO₂ (es un valor aproximado que cambia año a año según cómo se genera la electricidad). Con lo que aprendiste, vas a ayudarlo a leer sus números."]},"solucion":{}},{"slug":"tronco-2.s7.p2","orden":2,"grupo":"tronco-2.s7.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 300 kWh por mes y 0,4 kg de CO₂ por kWh, ¿cuántos kg de CO₂ emite la electricidad de la casa de Tomi en un mes?","unidad":"kg CO₂","decimales":0,"contexto":"La casa de Tomi: 300 kWh de luz por mes, 18 m³ de agua por mes, 5 kg de basura por día, 4 personas. Factor de la red: 0,4 kg CO₂ por kWh."},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"300 kWh × 0,4 kg/kWh = 120 kg de CO₂ por mes. En un año, unos 1.440 kg: casi una tonelada y media."}},{"slug":"tronco-2.s7.p3","orden":3,"grupo":"tronco-2.s7.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de agua por persona y por día usa la familia de Tomi? (18 m³ por mes, 4 personas, mes de 30 días)","unidad":"litros por persona por día","decimales":0,"contexto":"La casa de Tomi: 300 kWh de luz por mes, 18 m³ de agua por mes, 5 kg de basura por día, 4 personas. Factor de la red: 0,4 kg CO₂ por kWh."},"solucion":{"valor":150,"tolerancia":3,"explicacion":"18 m³ = 18.000 litros por mes. ÷ 30 días = 600 litros por día. ÷ 4 personas = 150 litros por persona por día."}},{"slug":"tronco-2.s7.p4","orden":4,"grupo":"tronco-2.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilos de basura por persona y por día genera la familia?","unidad":"kg por persona por día","decimales":2,"contexto":"La casa de Tomi: 300 kWh de luz por mes, 18 m³ de agua por mes, 5 kg de basura por día, 4 personas. Factor de la red: 0,4 kg CO₂ por kWh."},"solucion":{"valor":1.25,"tolerancia":0.025,"explicacion":"5 kg por día ÷ 4 personas = 1,25 kg por persona por día."}},{"slug":"tronco-2.s7.p5","orden":5,"grupo":"tronco-2.s7.p5","tipo":"opcion","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La estufa eléctrica de 2.000 W de la casa se usa 4 horas por día en invierno. ¿Qué parte de los 300 kWh del mes representa en 30 días?","opciones":[{"id":"o1","texto":"240 kWh: el 80 % de toda la factura"},{"id":"o2","texto":"8 kWh: casi nada de la factura"},{"id":"o3","texto":"2.000 kWh: más que toda la factura"},{"id":"o4","texto":"24 kWh: el 8 % de la factura"}],"contexto":"La casa de Tomi: 300 kWh de luz por mes. La estufa eléctrica de 2.000 W se usa 4 horas por día."},"solucion":{"clave":["o1"],"explicacion":"2 kW × 4 h = 8 kWh por día; × 30 días = 240 kWh. En invierno la estufa sola explicaría el 80 % del consumo: es el primer lugar donde mirar.","por_opcion":{"o3":"Hay que pasar a kW: 2 kW × 4 h × 30 días = 240 kWh."}}},{"slug":"tronco-2.s7.p6","orden":6,"grupo":"tronco-2.s7.p6","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Tomi arma una lista de cambios posibles para la casa. Ordenalos por cuánta energía por mes ahorran, de más a menos.","items":[{"id":"i1","texto":"Usar la estufa 2 horas menos por día (2.000 W)"},{"id":"i2","texto":"Apagar el aire acondicionado de un cuarto vacío, 3 h por día (1.000 W)"},{"id":"i3","texto":"Cambiar 5 lámparas de 40 W por LED de 9 W, 4 h por día"},{"id":"i4","texto":"Desenchufar dos cargadores en espera (0,5 W cada uno)"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Estufa: 2 kW × 2 h × 30 = 120 kWh. Aire: 1 kW × 3 h × 30 = 90. Lámparas: 5 × 31 W × 4 h × 30 ≈ 18,6. Cargadores: 1 W × 24 h × 30 = 0,72. Entre el primero y el último hay más de dos órdenes de magnitud.","valores":{"i1":"≈ 120 kWh por mes","i2":"≈ 90 kWh por mes","i3":"≈ 19 kWh por mes","i4":"≈ 0,7 kWh por mes"}}},{"slug":"tronco-2.s7.p7","orden":7,"grupo":"tronco-2.s7.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si Tomi desenchufa los cargadores, su casa baja el consumo a la mitad.","razones":[{"id":"r1","texto":"Porque los cargadores en espera consumen menos del 1 % del total"},{"id":"r2","texto":"Porque los cargadores son lo que más consume de la casa"},{"id":"r3","texto":"Porque desenchufar no ahorra nada nunca"}]},"solucion":{"valor":false,"explicacion":"Dos cargadores en espera suman menos de 1 kWh por mes sobre 300: menos del 0,3 %. Está bien hacerlo, pero el ahorro grande está en la estufa y la climatización.","clave":["r1"]}},{"slug":"tronco-2.s7.p8","orden":8,"grupo":"tronco-2.s7.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Tomi logra ahorrar 120 kWh por mes, ¿cuántos kg de CO₂ evita por año? (Factor de la red: 0,4 kg por kWh.)","unidad":"kg CO₂ por año","decimales":0},"solucion":{"valor":576,"tolerancia":11.52,"explicacion":"120 kWh × 12 meses = 1440 kWh por año. × 0,4 kg/kWh = 576 kg de CO₂ por año."}},{"slug":"tronco-2.s7.p8.v2","orden":8,"grupo":"tronco-2.s7.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Tomi logra ahorrar 90 kWh por mes, ¿cuántos kg de CO₂ evita por año? (Factor de la red: 0,4 kg por kWh.)","unidad":"kg CO₂ por año","decimales":0},"solucion":{"valor":432,"tolerancia":8.64,"explicacion":"90 kWh × 12 meses = 1080 kWh por año. × 0,4 kg/kWh = 432 kg de CO₂ por año."}},{"slug":"tronco-2.s7.p8.v3","orden":8,"grupo":"tronco-2.s7.p8","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si Tomi logra ahorrar 60 kWh por mes, ¿cuántos kg de CO₂ evita por año? (Factor de la red: 0,4 kg por kWh.)","unidad":"kg CO₂ por año","decimales":0},"solucion":{"valor":288,"tolerancia":5.76,"explicacion":"60 kWh × 12 meses = 720 kWh por año. × 0,4 kg/kWh = 288 kg de CO₂ por año."}},{"slug":"tronco-2.s7.p9","orden":9,"grupo":"tronco-2.s7.p9","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La hermana de Tomi escribe un resumen. Marcá los errores.","segmentos":[{"id":"s1","texto":"Gastamos 300 kWh por mes,"},{"id":"s2","texto":"que por un factor de 0,4 son 120 toneladas de CO₂ al mes."},{"id":"s3","texto":"La estufa es lo que más pesa en invierno,"},{"id":"s4","texto":"así que lo primero es desenchufar los cargadores."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Unidades bien puestas y prioridades por orden de magnitud: las dos cosas que aprendiste en esta unidad.","por_opcion":{"s2":"Son 120 kilos, no toneladas: 300 × 0,4 = 120 kg.","s4":"Por orden de magnitud, lo primero es la estufa y la climatización; los cargadores son lo último."}}},{"slug":"tronco-2.s7.p10","orden":10,"grupo":"tronco-2.s7.p10","tipo":"multiple","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conclusiones son correctas para la casa de Tomi? Marcá todas.","opciones":[{"id":"o1","texto":"En invierno, la estufa explica la mayor parte del consumo eléctrico"},{"id":"o2","texto":"El consumo de agua por persona se puede comparar con el de otras casas porque está en litros por persona por día"},{"id":"o3","texto":"Los cambios chicos suman, pero no reemplazan a los grandes"},{"id":"o4","texto":"La basura no se puede medir porque se tira todos los días"},{"id":"o5","texto":"Un kWh emite lo mismo en todos los países y todos los años"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El factor de emisión de la red depende de cómo se genera la electricidad en cada lugar y cada año. Todo lo demás es lectura de números con su unidad y su \"por\"."}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"tronco-3","rama":"tronco","orden":3,"nivel":0,"titulo_es":"Del saber al hacer","bajada_es":"Por qué cuesta cambiar, cómo se arma un hábito que dure, qué está en tus manos y cómo sumar a otros sin pelear.","objetivos_es":["Explicar por qué saber algo no alcanza para hacerlo, sin culpa","Diseñar un hábito con disparador, rutina y recompensa, empezando chico","Distinguir lo que depende de vos de lo que depende de los sistemas, y actuar en los dos","Elegir acciones por impacto y reconocer el efecto rebote","Hablar de ambiente con otras personas de forma concreta, esperanzada y sin sermones"],"repasa":["tronco-1","tronco-2"],"requiere_tronco":0,"fuentes":["bit-east","lally-2010-habitos","wynes-nicholas-2017","ecoansiedad-review","unesco-ods","ley-27621-eai","naaee-guidelines"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"tronco-3.s1","orden":1,"tipo":"leccion","titulo_es":"Saber no alcanza","bajada_es":"Por qué la información sola casi nunca cambia lo que hacemos, y qué sí lo hace.","minutos":10,"pasos":[{"slug":"tronco-3.s1.p1","orden":1,"grupo":"tronco-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La brecha entre querer y hacer","cuerpo":["Mucha gente sabe que conviene cerrar la canilla mientras se cepilla los dientes, y aun así la deja abierta. No es falta de información ni de buena intención: es que la mayor parte de lo que hacemos en un día sale en piloto automático.","A esa distancia entre lo que queremos hacer y lo que efectivamente hacemos se la llama brecha entre intención y acción. Es normal, le pasa a todo el mundo, y se puede achicar trabajando sobre el entorno y la costumbre, no sobre la culpa."],"destacado":{"valor":"Hábito > información","texto":"lo que se repite en piloto automático pesa más que lo que se sabe."}},"solucion":{}},{"slug":"tronco-3.s1.p2","orden":2,"grupo":"tronco-3.s1.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Juan sabe que el agua es valiosa pero se sigue duchando 20 minutos. ¿Cuál es la explicación más probable?","opciones":[{"id":"o1","texto":"Tiene la costumbre armada y nada en su entorno la frena"},{"id":"o2","texto":"No le importa nada el ambiente ni el agua que gasta"},{"id":"o3","texto":"Le falta información sobre cuánta agua usa la ducha"},{"id":"o4","texto":"Es imposible ducharse en menos tiempo"}]},"solucion":{"clave":["o1"],"explicacion":"Saber y hacer son cosas distintas. Juzgar a Juan como alguien a quien \"no le importa\" suele ser falso y además no ayuda a que cambie.","por_opcion":{"o3":"Puede ser, pero el caso dice que ya lo sabe: la información sola no alcanzó."}}},{"slug":"tronco-3.s1.p3","orden":3,"grupo":"tronco-3.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las barreras reales","cuerpo":["Cuando una acción no se hace, casi siempre hay una barrera concreta: cuesta dinero, lleva tiempo, es incómoda, nadie alrededor la hace, o simplemente no hay a mano lo necesario (no hay contenedor, no hay bicisenda, no hay tiempo a la mañana).","Identificar la barrera real es el primer paso. Si el problema es que el contenedor de reciclables está lejos, un folleto sobre reciclaje no va a cambiar nada; acercar el contenedor, sí."],"lista":["Costo: sale caro o parece caro","Esfuerzo: lleva tiempo o es incómodo","Entorno: falta lo necesario a mano","Norma social: nadie alrededor lo hace","Olvido: no hay un recordatorio en el momento justo"]},"solucion":{}},{"slug":"tronco-3.s1.p4","orden":4,"grupo":"tronco-3.s1.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de barrera es cada una?","grupos":[{"id":"g1","nombre":"Entorno o esfuerzo"},{"id":"g2","nombre":"Norma social o costumbre"}],"items":[{"id":"i1","texto":"El punto verde queda a 20 cuadras"},{"id":"i2","texto":"En la oficina nadie trae su taza"},{"id":"i3","texto":"No hay lugar en la cocina para separar residuos"},{"id":"i4","texto":"En casa siempre se hizo así"},{"id":"i5","texto":"La bicicleta está en un cuarto trabado"},{"id":"i6","texto":"Me da vergüenza ser el único que separa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las barreras del entorno se resuelven cambiando el lugar; las sociales, cambiando lo que se ve hacer a otros. Por eso las soluciones también son distintas."}},{"slug":"tronco-3.s1.p5","orden":5,"grupo":"tronco-3.s1.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué estrategias atacan barreras reales y no solo \"informan\"? Marcá todas.","opciones":[{"id":"o1","texto":"Poner un tacho para reciclables al lado del tacho común"},{"id":"o2","texto":"Dejar la bici lista en la entrada la noche anterior"},{"id":"o3","texto":"Acordar con amigos ir juntos al punto verde"},{"id":"o4","texto":"Leer otro artículo sobre la importancia de reciclar"},{"id":"o5","texto":"Sentirse culpable cada vez que no se hace"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Cambiar el entorno y sumarse con otros funciona mejor que acumular información o culpa. La culpa, además, desgasta y hace abandonar."}},{"slug":"tronco-3.s1.p6","orden":6,"grupo":"tronco-3.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Sentir mucha culpa es la mejor forma de lograr que alguien cambie un hábito.","razones":[{"id":"r1","texto":"Porque la culpa lleva a evitar el tema más que a actuar"},{"id":"r2","texto":"Porque la culpa es la única emoción que mueve a actuar"},{"id":"r3","texto":"Porque los hábitos no se pueden cambiar"}]},"solucion":{"valor":false,"explicacion":"La culpa intensa suele generar evitación: la persona deja de pensar en el tema para no sentirse mal. Funcionan mejor los pasos concretos, el apoyo de otros y ver resultados.","clave":["r1"]}},{"slug":"tronco-3.s1.p7","orden":7,"grupo":"tronco-3.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ansiedad ambiental: normal, y trabajable","cuerpo":["Conocer los problemas ambientales puede generar angustia. Tiene nombre —ecoansiedad— y es una reacción comprensible, sobre todo en gente joven. No es una enfermedad ni una exageración.","Lo que más ayuda es pasar de la preocupación a la acción concreta y compartida: hacer algo que dependa de uno, con otros, y ver que produce un cambio. La esperanza no es optimismo ingenuo: es saber que hay algo para hacer y hacerlo."]},"solucion":{}},{"slug":"tronco-3.s1.p8","orden":8,"grupo":"tronco-3.s1.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una amiga te dice que siente angustia cada vez que lee noticias sobre el clima. ¿Qué respuesta ayuda más?","opciones":[{"id":"o1","texto":"Validar lo que siente y proponerle hacer algo juntas"},{"id":"o2","texto":"Decirle que no exagere, que no es para tanto y ya se le pasa"},{"id":"o3","texto":"Mandarle más noticias para que esté mejor informada"},{"id":"o4","texto":"Decirle que ya no hay nada que hacer"}]},"solucion":{"clave":["o1"],"explicacion":"Validar y actuar juntos: reconocer la emoción sin minimizarla y convertirla en una acción compartida y alcanzable.","por_opcion":{"o3":"Más información sin acción suele aumentar la angustia en vez de bajarla."}}},{"slug":"tronco-3.s1.p9","orden":9,"grupo":"tronco-3.s1.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para destrabar una acción que no sale.","items":[{"id":"i1","texto":"Elegir una acción concreta que quieras hacer"},{"id":"i2","texto":"Identificar la barrera real que la frena"},{"id":"i3","texto":"Cambiar algo del entorno para bajar esa barrera"},{"id":"i4","texto":"Probar una semana y ver qué pasó"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero qué, después por qué no sale, después el cambio, y al final medir. Es un ciclo: si no funcionó, se vuelve al paso dos."}},{"slug":"tronco-3.s1.p10","orden":10,"grupo":"tronco-3.s1.p10","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este razonamiento y marcá lo que no ayuda.","segmentos":[{"id":"s1","texto":"Quiero dejar de usar bolsas de un solo uso."},{"id":"s2","texto":"Si me olvido las bolsas, es porque soy un desastre."},{"id":"s3","texto":"Voy a dejar las bolsas de tela colgadas en la puerta."},{"id":"s4","texto":"Si igual me olvido una vez, ya fracasé y no vale la pena seguir."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las frases que convierten un olvido en un juicio sobre la persona son las que hacen abandonar. Las que cambian el entorno son las que ayudan.","por_opcion":{"s2":"Olvidarse es normal: es un problema de recordatorio, no de persona.","s4":"Un olvido no borra el hábito: lo que cuenta es la mayoría de las veces."}}},{"slug":"tronco-3.s1.p11","orden":11,"grupo":"tronco-3.s1.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá la idea.","texto":"Para cerrar la brecha entre intención y acción conviene cambiar el {{0}} y apoyarse en {{1}}, más que sumar {{2}}.","banco":[{"id":"w1","texto":"entorno"},{"id":"w2","texto":"otras personas"},{"id":"w3","texto":"culpa"},{"id":"w4","texto":"información"},{"id":"w5","texto":"castigos"},{"id":"w6","texto":"ruido"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Entorno y apoyo social son las dos palancas más fuertes. La culpa y la información sola, las más débiles."}},{"slug":"tronco-3.s1.p12","orden":12,"grupo":"tronco-3.s1.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada barrera con una forma de bajarla.","izquierda":[{"id":"a1","texto":"Me olvido las bolsas de tela"},{"id":"a2","texto":"Nadie en la oficina separa residuos"},{"id":"a3","texto":"El punto verde queda lejos"},{"id":"a4","texto":"La bici está trabada en el depósito"}],"derecha":[{"id":"b1","texto":"Dejarlas colgadas junto a la puerta"},{"id":"b2","texto":"Proponer un tacho compartido y empezar a usarlo a la vista"},{"id":"b3","texto":"Juntar varios meses y llevar todo de una vez con un vecino"},{"id":"b4","texto":"Guardarla la noche anterior a mano en la entrada"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada barrera tiene su palanca: recordatorio, norma social, logística o entorno. Nombrar la barrera es la mitad de la solución."}}]},{"slug":"tronco-3.s2","orden":2,"tipo":"leccion","titulo_es":"Cómo se arma un hábito","bajada_es":"Disparador, rutina y recompensa: la receta para que una acción salga sola.","minutos":11,"pasos":[{"slug":"tronco-3.s2.p1","orden":1,"grupo":"tronco-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las tres piezas de un hábito","cuerpo":["Un hábito es una acción que se repite tantas veces en el mismo contexto que termina saliendo casi sin pensar. Tiene tres piezas: un disparador (algo que avisa: un lugar, una hora, otra acción), la rutina (lo que se hace) y una recompensa (algo que hace que valga la pena repetir).","Por ejemplo: al terminar de cenar (disparador), tirar los restos de comida en la compostera (rutina) y ver cómo crece la tierra para las plantas (recompensa)."]},"solucion":{}},{"slug":"tronco-3.s2.p2","orden":2,"grupo":"tronco-3.s2.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pieza del hábito con su ejemplo.","izquierda":[{"id":"a1","texto":"Disparador"},{"id":"a2","texto":"Rutina"},{"id":"a3","texto":"Recompensa"}],"derecha":[{"id":"b1","texto":"Al entrar a la ducha"},{"id":"b2","texto":"Poner un temporizador de cinco minutos"},{"id":"b3","texto":"Ver la cuenta de litros ahorrados de la semana"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Sin disparador, la rutina depende de acordarse; sin recompensa, se abandona. Las tres piezas juntas son las que la sostienen."}},{"slug":"tronco-3.s2.p3","orden":3,"grupo":"tronco-3.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Empezar ridículamente chico","cuerpo":["Los hábitos que duran suelen empezar muy chicos: no \"voy a ir en bici a todos lados\", sino \"los martes voy en bici a la facultad\". Una acción chica que se cumple le gana a una grande que se abandona a la semana.","Otra técnica útil es \"apilar\": pegar el hábito nuevo a uno que ya existe. \"Después de cargar el lavarropas, junto los papeles para reciclar.\" El hábito viejo funciona como disparador del nuevo."],"destacado":{"valor":"Chico y fijo","texto":"mejor una acción mínima todos los días que una enorme una sola vez."}},"solucion":{}},{"slug":"tronco-3.s2.p4","orden":4,"grupo":"tronco-3.s2.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál de estos planes tiene más chances de convertirse en hábito?","opciones":[{"id":"o1","texto":"\"Después de lavar los platos, saco los reciclables\""},{"id":"o2","texto":"\"Voy a ser una persona más sustentable en todo\""},{"id":"o3","texto":"\"Desde mañana cambio todo lo que hago en casa\""},{"id":"o4","texto":"\"Algún día voy a empezar a separar residuos\""}]},"solucion":{"clave":["o1"],"explicacion":"Es concreta, chica y está pegada a algo que ya pasa todos los días. Las otras son deseos, no planes.","por_opcion":{"o3":"Cambiar todo a la vez es difícil de sostener: conviene de a una cosa y bien concreta."}}},{"slug":"tronco-3.s2.p5","orden":5,"grupo":"tronco-3.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"¿Cuánto tarda en armarse?","cuerpo":["Se dice mucho que un hábito se arma en 21 días, pero ese número no tiene respaldo. Un estudio de 2009 publicado en 2010 (Lally y colegas) siguió a personas que intentaban incorporar hábitos simples: la mediana fue de 66 días, con casos que tardaron desde unas semanas hasta más de ocho meses.","El mismo estudio encontró algo alentador: saltearse un día no arruinaba el proceso. Lo que cuenta es la repetición en el tiempo, no la perfección."],"destacado":{"valor":"66 días","texto":"fue la mediana para que un hábito simple se volviera automático en ese estudio."}},"solucion":{}},{"slug":"tronco-3.s2.p6","orden":6,"grupo":"tronco-3.s2.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un hábito se arma exactamente en 21 días para todo el mundo.","razones":[{"id":"r1","texto":"Porque el tiempo varía mucho y la mediana medida fue de 66 días"},{"id":"r2","texto":"Porque los hábitos se arman en una semana"},{"id":"r3","texto":"Porque los hábitos no se pueden medir"}]},"solucion":{"valor":false,"explicacion":"Ese número es un mito popular. En el estudio de Lally la mediana fue de 66 días, con una variación enorme entre personas y entre hábitos.","clave":["r1"]}},{"slug":"tronco-3.s2.p7","orden":7,"grupo":"tronco-3.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un día te salteás el hábito nuevo, tenés que empezar de cero."},"solucion":{"valor":false,"explicacion":"En el estudio de Lally, faltar un día no afectó de forma importante la formación del hábito. Lo que importa es volver al día siguiente."}},{"slug":"tronco-3.s2.p8","orden":8,"grupo":"tronco-3.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuatro palancas: fácil, atractivo, social, a tiempo","cuerpo":["Un marco muy usado para diseñar cambios de comportamiento resume las palancas en cuatro: hacerlo fácil (menos pasos), atractivo (que valga la pena), social (que otros lo hagan y se vea) y oportuno (que el recordatorio llegue en el momento justo).","Si una acción no sale, conviene preguntarse cuál de las cuatro falta. Casi siempre es la primera: todavía es demasiado difícil."],"lista":["Fácil: sacar pasos del camino","Atractivo: una recompensa o algo que guste","Social: hacerlo con otros o a la vista","A tiempo: el aviso justo antes de que haga falta"]},"solucion":{}},{"slug":"tronco-3.s2.p9","orden":9,"grupo":"tronco-3.s2.p9","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué palanca usa cada idea?","grupos":[{"id":"g1","nombre":"Fácil"},{"id":"g2","nombre":"Social"},{"id":"g3","nombre":"A tiempo"}],"items":[{"id":"i1","texto":"Dejar la taza reutilizable en la mochila"},{"id":"i2","texto":"Armar un grupo del edificio para compostar"},{"id":"i3","texto":"Una alarma los jueves a la noche para sacar los reciclables"},{"id":"i4","texto":"Poner el tacho de orgánicos al lado de la mesada"},{"id":"i5","texto":"Contar en la familia cuántos litros ahorraron"},{"id":"i6","texto":"Un cartel en la puerta: \"¿llevás las bolsas?\""}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Muchas ideas combinan palancas, pero conviene saber cuál es la principal: así, si falla, sabés qué ajustar."}},{"slug":"tronco-3.s2.p10","orden":10,"grupo":"tronco-3.s2.p10","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para diseñar un hábito nuevo.","items":[{"id":"i1","texto":"Elegir una acción chica y concreta"},{"id":"i2","texto":"Pegarla a algo que ya hacés todos los días"},{"id":"i3","texto":"Preparar el entorno para que sea fácil"},{"id":"i4","texto":"Registrar cada vez que la hacés"},{"id":"i5","texto":"Revisar a las semanas y ajustar"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Acción mínima, disparador existente, entorno preparado, registro y revisión. Es el mismo esquema sirva para agua, energía o residuos."}},{"slug":"tronco-3.s2.p11","orden":11,"grupo":"tronco-3.s2.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Camila quiere llevar su botella reutilizable pero siempre se la olvida. ¿Qué palanca le falta más claramente?","opciones":[{"id":"o1","texto":"Que sea fácil y a tiempo: dejar la botella lista junto a las llaves"},{"id":"o2","texto":"Más información sobre los plásticos de un solo uso"},{"id":"o3","texto":"Una botella más cara y linda"},{"id":"o4","texto":"Sentirse mal cada vez que compra una botella descartable"}]},"solucion":{"clave":["o1"],"explicacion":"El problema es de olvido: la solución es poner la botella en el camino, en el lugar y el momento justos.","por_opcion":{"o3":"Puede ayudar a que sea atractiva, pero el problema del caso es el olvido."}}},{"slug":"tronco-3.s2.p12","orden":12,"grupo":"tronco-3.s2.p12","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"En el estudio de Lally, ¿cuántos días fue la mediana para que un hábito simple se volviera automático? Estimá.","min":5,"max":250,"paso":1,"unidad":"días","escala":"lineal"},"solucion":{"valor":66,"banda":"lineal","explicacion":"La mediana fue de 66 días, con casos de 18 a 254. Mucho más que los \"21 días\" que se repiten por ahí."}},{"slug":"tronco-3.s2.p13","orden":13,"grupo":"tronco-3.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de hábito y marcá lo que va a hacer que falle.","segmentos":[{"id":"s1","texto":"Quiero compostar los restos de la cocina."},{"id":"s2","texto":"Voy a hacerlo cuando me acuerde, sin horario fijo."},{"id":"s3","texto":"Pongo el balde de restos al lado de la pileta."},{"id":"s4","texto":"Y el primer día voy a armar tres composteras distintas a la vez."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Disparador fijo y empezar chico: los dos errores más comunes al armar un hábito son justo los contrarios.","por_opcion":{"s2":"Sin disparador, depende de acordarse: es la receta del olvido.","s4":"Empezar demasiado grande hace abandonar: mejor una sola y chica."}}}]},{"slug":"tronco-3.s3","orden":3,"tipo":"leccion","titulo_es":"Lo tuyo y lo de todos","bajada_es":"Qué depende de cada persona, qué depende de los sistemas, y por qué hacen falta las dos cosas.","minutos":10,"pasos":[{"slug":"tronco-3.s3.p1","orden":1,"grupo":"tronco-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos escalas que se necesitan","cuerpo":["Muchas decisiones ambientales las toma cada persona: cuánta agua usa, qué come, cómo se mueve. Otras las toman los sistemas: cómo se genera la electricidad, si hay transporte público bueno, si el municipio recoge los reciclables.","A veces se discute si \"importa lo individual o lo colectivo\", como si hubiera que elegir. En la práctica se empujan entre sí: la gente que actúa pide mejores sistemas, y los mejores sistemas hacen más fácil actuar."]},"solucion":{}},{"slug":"tronco-3.s3.p2","orden":2,"grupo":"tronco-3.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Depende sobre todo de una persona o de un sistema?","grupos":[{"id":"g1","nombre":"Decisión personal o de la casa"},{"id":"g2","nombre":"Decisión de un sistema"}],"items":[{"id":"i1","texto":"Cuánto tiempo dura tu ducha"},{"id":"i2","texto":"Qué fuentes generan la electricidad del país"},{"id":"i3","texto":"Separar los residuos en tu cocina"},{"id":"i4","texto":"Si hay recolección diferenciada en tu barrio"},{"id":"i5","texto":"Qué comés en la cena"},{"id":"i6","texto":"Cuántas bicisendas tiene la ciudad"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos columnas importan. Y la segunda también se puede empujar: votando, participando, pidiendo y usando lo que existe."}},{"slug":"tronco-3.s3.p3","orden":3,"grupo":"tronco-3.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tus círculos de influencia","cuerpo":["Cada persona influye en varios círculos, no solo en su casa: la familia, los amigos, la escuela o el trabajo, el barrio, y como ciudadana. En cada uno hay acciones posibles.","Proponer que la escuela separe residuos, sumarse a una asamblea del barrio o pedirle al municipio un contenedor también son acciones ambientales, y a veces mueven más que cualquier cambio en casa."],"lista":["Personal: tus hábitos","Casa: las reglas y compras de tu hogar","Escuela o trabajo: lo que se decide en grupo","Barrio: lo que se hace con vecinos","Ciudadanía: lo que se pide y se vota"]},"solucion":{}},{"slug":"tronco-3.s3.p4","orden":4,"grupo":"tronco-3.s3.p4","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená estos círculos de influencia de más cercano a más amplio.","items":[{"id":"i1","texto":"Tus propios hábitos"},{"id":"i2","texto":"Las reglas de tu casa"},{"id":"i3","texto":"Tu escuela o tu trabajo"},{"id":"i4","texto":"Tu barrio"},{"id":"i5","texto":"Las decisiones de tu ciudad"}],"extremos":["Más cercano","Más amplio"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los círculos más amplios son más difíciles de mover solo, pero cuando se mueven, cambian las cosas para miles de personas a la vez."}},{"slug":"tronco-3.s3.p5","orden":5,"grupo":"tronco-3.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El contagio social","cuerpo":["Lo que hacemos se contagia. Cuando alguien ve que sus vecinos instalan paneles solares, compostan o van en bici, es más probable que lo haga. Varios estudios encontraron que la adopción de paneles solares se agrupa por barrio justamente por este efecto de ver a otros hacerlo.","Por eso una acción visible vale doble: el ahorro propio y el ejemplo que abre la puerta a otros. Hacer las cosas a la vista, sin sermonear, es una forma de influencia."]},"solucion":{}},{"slug":"tronco-3.s3.p6","orden":6,"grupo":"tronco-3.s3.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Martina empieza a ir en bici al trabajo y deja la bici en la entrada de la oficina. ¿Por qué eso puede tener más impacto que solo su propio viaje?","opciones":[{"id":"o1","texto":"Porque sus compañeros la ven y aumenta la chance de que otros prueben"},{"id":"o2","texto":"Porque la bici en la entrada ocupa menos lugar que un auto"},{"id":"o3","texto":"Porque así la bici no se oxida con la lluvia"},{"id":"o4","texto":"Porque la empresa le va a pagar más"}]},"solucion":{"clave":["o1"],"explicacion":"El contagio social multiplica las acciones visibles. Es una de las razones por las que lo individual y lo colectivo no están separados.","por_opcion":{"o3":"Puede ser cierto, pero no explica el impacto más allá de ella."}}},{"slug":"tronco-3.s3.p7","orden":7,"grupo":"tronco-3.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los grandes cambios dependen de gobiernos y empresas, lo que hace cada persona no tiene ningún efecto.","razones":[{"id":"r1","texto":"Porque lo individual contagia y empuja cambios más grandes"},{"id":"r2","texto":"Porque los gobiernos no toman decisiones ambientales"},{"id":"r3","texto":"Porque solo lo individual importa"}]},"solucion":{"valor":false,"explicacion":"Lo individual tiene efecto directo (lo que ahorra cada persona) e indirecto: contagia, crea demanda de mejores productos y sostiene los pedidos de cambios más grandes.","clave":["r1"]}},{"slug":"tronco-3.s3.p8","orden":8,"grupo":"tronco-3.s3.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles son formas de influir en un sistema, más allá de tu casa? Marcá todas.","opciones":[{"id":"o1","texto":"Proponer en la escuela un sistema de separación de residuos"},{"id":"o2","texto":"Participar de una audiencia pública sobre un proyecto del barrio"},{"id":"o3","texto":"Pedirle al municipio una bicisenda con otros vecinos"},{"id":"o4","texto":"Elegir comprar a comercios que reducen envases"},{"id":"o5","texto":"Esperar a que otro lo resuelva"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Proponer, participar, pedir en grupo y elegir dónde comprar son formas de empujar sistemas. Las verás en profundidad en la rama de Comunidad."}},{"slug":"tronco-3.s3.p9","orden":9,"grupo":"tronco-3.s3.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una acción personal puede terminar cambiando un sistema.","items":[{"id":"i1","texto":"Unos vecinos empiezan a compostar en sus casas"},{"id":"i2","texto":"Otros ven que funciona y se suman"},{"id":"i3","texto":"El grupo le pide al municipio una compostera comunitaria"},{"id":"i4","texto":"El municipio la instala en la plaza"},{"id":"i5","texto":"El compost desaparece solo a los pocos días"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"De lo personal a lo colectivo, y de ahí al sistema. El señuelo no tiene relación: el compost no desaparece, se convierte en tierra."}},{"slug":"tronco-3.s3.p10","orden":10,"grupo":"tronco-3.s3.p10","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las acciones personales y los cambios de {{0}} no compiten: las personas que actúan {{1}} mejores sistemas, y los mejores sistemas hacen más {{2}} actuar.","banco":[{"id":"w1","texto":"sistema"},{"id":"w2","texto":"piden"},{"id":"w3","texto":"fácil"},{"id":"w4","texto":"difícil"},{"id":"w5","texto":"olvidan"},{"id":"w6","texto":"caro"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Es un círculo que se refuerza. Por eso el árbol enseña las dos escalas."}},{"slug":"tronco-3.s3.p11","orden":11,"grupo":"tronco-3.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta discusión y marcá las frases que plantean una falsa opción.","segmentos":[{"id":"s1","texto":"Separar residuos en casa está bien,"},{"id":"s2","texto":"pero si no hay recolección diferenciada, no sirve para nada hacerlo."},{"id":"s3","texto":"Por eso también vale pedirle al municipio que la implemente."},{"id":"s4","texto":"O cambiás tus hábitos o cambiás el sistema: las dos cosas a la vez no se puede."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El \"o una cosa o la otra\" es la trampa más común de estas discusiones. Casi siempre la respuesta es \"las dos\".","por_opcion":{"s2":"Sirve igual: ordena la casa, alimenta la demanda y hay puntos verdes y cooperativas que reciben materiales.","s4":"Se puede, y conviene: cada una empuja a la otra."}}},{"slug":"tronco-3.s3.p12","orden":12,"grupo":"tronco-3.s3.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En tu escuela no hay dónde separar residuos. ¿Qué acción sale de tu casa y empuja al sistema de la escuela?","opciones":[{"id":"o1","texto":"Proponer con compañeros un tacho de reciclables por aula"},{"id":"o2","texto":"Separar en tu casa y no decir nada en la escuela"},{"id":"o3","texto":"Esperar a que la escuela lo decida sola algún día"},{"id":"o4","texto":"Tirar todo junto porque en la escuela no importa"}]},"solucion":{"clave":["o1"],"explicacion":"Es una acción colectiva en un círculo cercano: pequeña para empezar y capaz de cambiar lo que hacen cientos de personas por día.","por_opcion":{"o3":"Los sistemas cambian cuando alguien lo pide: esperar suele ser esperar para siempre."}}}]},{"slug":"tronco-3.s4","orden":4,"tipo":"leccion","titulo_es":"Elegir por impacto","bajada_es":"Con tiempo y energía limitados, conviene empezar por lo que más pesa. Cómo decidir sin volverse loco.","minutos":10,"pasos":[{"slug":"tronco-3.s4.p1","orden":1,"grupo":"tronco-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Impacto por esfuerzo","cuerpo":["No todas las acciones valen lo mismo, ni cuestan lo mismo. Una buena forma de elegir es mirar dos cosas a la vez: cuánto impacto tienen y cuánto esfuerzo te piden a vos, en tu situación.","Las mejores para empezar son las de alto impacto y bajo esfuerzo. Después, las de alto impacto aunque cuesten más. Las de bajo impacto y bajo esfuerzo están bien para sumar; las de bajo impacto y mucho esfuerzo, conviene dejarlas para el final."]},"solucion":{}},{"slug":"tronco-3.s4.p2","orden":2,"grupo":"tronco-3.s4.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá estas acciones para una familia con auto que vive cerca del trabajo.","grupos":[{"id":"g1","nombre":"Alto impacto, bajo esfuerzo"},{"id":"g2","nombre":"Alto impacto, más esfuerzo"},{"id":"g3","nombre":"Bajo impacto, bajo esfuerzo"}],"items":[{"id":"i1","texto":"Ir caminando al trabajo, que queda a diez cuadras"},{"id":"i2","texto":"Vender el segundo auto"},{"id":"i3","texto":"Desenchufar el cargador"},{"id":"i4","texto":"Bajar un grado la calefacción en invierno"},{"id":"i5","texto":"Aislar el techo de la casa"},{"id":"i6","texto":"Apagar la luz del pasillo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"El mismo cambio puede ser fácil para una familia y difícil para otra: por eso la matriz se arma con tu situación, no con una lista general."}},{"slug":"tronco-3.s4.p3","orden":3,"grupo":"tronco-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los tres grandes","cuerpo":["Para la mayoría de los hogares de ingresos medios y altos, la huella se concentra en tres áreas: transporte (sobre todo auto y avión), energía de la casa (calefacción, refrigeración, agua caliente) y alimentación (sobre todo la carne vacuna).","No es una lista de prohibiciones: es un mapa de dónde está el peso. Un cambio en cualquiera de esas tres áreas suele valer más que diez cambios en otras."],"datos":{"tipo":"barras","titulo":"Ahorro estimado por persona y por año","unidad":"t CO₂e","filas":[{"etiqueta":"Vivir sin auto","valor":2.4},{"etiqueta":"Evitar un vuelo transatlántico ida y vuelta","valor":1.6},{"etiqueta":"Dieta basada en plantas","valor":0.8},{"etiqueta":"Lavar con agua fría","valor":0.25},{"etiqueta":"Reciclar","valor":0.21}],"nota":"Fuente: Wynes y Nicholas (2017), países de altos ingresos. Valores aproximados."}},"solucion":{}},{"slug":"tronco-3.s4.p4","orden":4,"grupo":"tronco-3.s4.p4","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"Según el gráfico, ¿cuáles de estas acciones ahorran más de media tonelada por año? Marcá todas.","opciones":[{"id":"o1","texto":"Vivir sin auto"},{"id":"o2","texto":"Evitar un vuelo transatlántico"},{"id":"o3","texto":"Una dieta basada en plantas"},{"id":"o4","texto":"Reciclar"},{"id":"o5","texto":"Lavar con agua fría"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Leer un gráfico es buscar el umbral y comparar: tres de las cinco barras superan 0,5 toneladas."}},{"slug":"tronco-3.s4.p5","orden":5,"grupo":"tronco-3.s4.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según el gráfico, ¿cuántas veces más ahorra vivir sin auto que reciclar (0,2 t)? Redondeá a entero.","unidad":"veces","decimales":0},"solucion":{"valor":12,"tolerancia":0.6,"explicacion":"2,4 ÷ 0,2 = 12, o sea unas 12 veces. No quiere decir que reciclar no sirva: quiere decir dónde está el peso."}},{"slug":"tronco-3.s4.p5.v2","orden":5,"grupo":"tronco-3.s4.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según el gráfico, ¿cuántas veces más ahorra evitar un vuelo transatlántico que reciclar (0,2 t)? Redondeá a entero.","unidad":"veces","decimales":0},"solucion":{"valor":8,"tolerancia":0.6,"explicacion":"1,6 ÷ 0,2 = 8, o sea unas 8 veces. No quiere decir que reciclar no sirva: quiere decir dónde está el peso."}},{"slug":"tronco-3.s4.p5.v3","orden":5,"grupo":"tronco-3.s4.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según el gráfico, ¿cuántas veces más ahorra una dieta basada en plantas que reciclar (0,2 t)? Redondeá a entero.","unidad":"veces","decimales":0},"solucion":{"valor":4,"tolerancia":0.6,"explicacion":"0,8 ÷ 0,2 = 4, o sea unas 4 veces. No quiere decir que reciclar no sirva: quiere decir dónde está el peso."}},{"slug":"tronco-3.s4.p6","orden":6,"grupo":"tronco-3.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuidado con lo que parece verde","cuerpo":["Hay acciones que se sienten muy ambientales y pesan poco (como cambiar la bombilla del patio) y otras que no parecen ambientales y pesan mucho (como aislar el techo o elegir dónde vivir). La intuición falla porque vemos lo que se ve: el envase, la bolsa, la pajita.","Pensar en impacto no es despreciar lo chico, es no quedarse solo ahí. Y es desconfiar de quien vende algo \"verde\" que en realidad cambia poco."]},"solucion":{}},{"slug":"tronco-3.s4.p7","orden":7,"grupo":"tronco-3.s4.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las acciones más visibles, como no usar pajita, son siempre las de mayor impacto.","razones":[{"id":"r1","texto":"Porque lo que más se ve no es necesariamente lo que más pesa"},{"id":"r2","texto":"Porque las pajitas son la principal fuente de emisiones del mundo"},{"id":"r3","texto":"Porque ninguna acción individual tiene impacto"}]},"solucion":{"valor":false,"explicacion":"La visibilidad y el impacto no van juntos. Evitar la pajita reduce residuos plásticos, pero en huella de carbono pesa mucho menos que el transporte o la calefacción.","clave":["r1"]}},{"slug":"tronco-3.s4.p8","orden":8,"grupo":"tronco-3.s4.p8","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una familia tiene tiempo para un solo cambio este mes. Viven en una zona fría, la casa pierde calor por el techo y calefaccionan con estufas eléctricas. ¿Cuál conviene priorizar?","opciones":[{"id":"o1","texto":"Mejorar la aislación del techo"},{"id":"o2","texto":"Cambiar las bolsas del supermercado por bolsas de tela"},{"id":"o3","texto":"Desenchufar todos los cargadores de noche"},{"id":"o4","texto":"Comprar productos con envases reciclables"}]},"solucion":{"clave":["o1"],"explicacion":"La calefacción es el gran consumo de esa casa, y el techo es por donde se escapa. Atacar la mayor pérdida es la regla de oro.","por_opcion":{"o3":"Ahorra algo, pero muy poco comparado con la calefacción en una casa que pierde calor."}}},{"slug":"tronco-3.s4.p9","orden":9,"grupo":"tronco-3.s4.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la forma de decidir qué acción hacer primero.","items":[{"id":"i1","texto":"Anotar dónde se usa más energía, agua o materiales en tu vida"},{"id":"i2","texto":"Listar acciones posibles para esos puntos"},{"id":"i3","texto":"Estimar impacto y esfuerzo de cada una"},{"id":"i4","texto":"Elegir la de mayor impacto que puedas sostener"},{"id":"i5","texto":"Hacer la que te recomendó el anuncio más llamativo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Medir, listar, estimar y elegir: es la misma lógica de órdenes de magnitud que viste en la unidad anterior, aplicada a tu vida."}},{"slug":"tronco-3.s4.p10","orden":10,"grupo":"tronco-3.s4.p10","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Para una persona que vuela a Europa una vez al año y vive a 30 cuadras del trabajo, ordená por impacto estimado.","items":[{"id":"i1","texto":"Evitar ese vuelo de ida y vuelta"},{"id":"i2","texto":"Ir en transporte público en lugar de auto"},{"id":"i3","texto":"Reciclar todos los envases"},{"id":"i4","texto":"Usar bolsas de tela"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los números exactos cambian según el vuelo, el auto y el reciclaje disponible, pero el orden de magnitud se mantiene: por eso se puede ordenar sin la cifra exacta.","valores":{"i1":"del orden de una tonelada o más","i2":"cientos de kilos por año","i3":"del orden de cien o doscientos kilos","i4":"unos pocos kilos"}}},{"slug":"tronco-3.s4.p11","orden":11,"grupo":"tronco-3.s4.p11","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan y marcá los puntos donde se pierde el foco.","segmentos":[{"id":"s1","texto":"Mi huella más grande es el auto, que uso para todo."},{"id":"s2","texto":"Así que este mes voy a cambiar el cepillo de dientes por uno de bambú"},{"id":"s3","texto":"y a probar ir en colectivo dos días por semana."},{"id":"s4","texto":"Y si el colectivo tarda más, lo dejo y listo: ya hice lo del cepillo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Identificar lo grande es el primer paso; sostener el cambio ahí es el importante. Los gestos chicos no compensan.","por_opcion":{"s2":"Está bien, pero no toca lo que acaba de identificar como lo más grande.","s4":"Usa la acción chica como excusa para abandonar la grande."}}},{"slug":"tronco-3.s4.p12","orden":12,"grupo":"tronco-3.s4.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá la regla para elegir.","texto":"Conviene empezar por las acciones de {{0}} y {{1}}, y dejar para el final las de poco impacto y mucho {{2}}.","banco":[{"id":"w1","texto":"alto impacto"},{"id":"w2","texto":"bajo esfuerzo"},{"id":"w3","texto":"esfuerzo"},{"id":"w4","texto":"bajo impacto"},{"id":"w5","texto":"alto costo"},{"id":"w6","texto":"poco tiempo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Impacto por esfuerzo, en tu situación. La matriz cambia de persona en persona, pero la regla es la misma."}}]},{"slug":"tronco-3.s5","orden":5,"tipo":"leccion","titulo_es":"Hablar de ambiente sin pelear","bajada_es":"Cómo contar lo que aprendiste para que otros se sumen, en vez de ponerse a la defensiva.","minutos":10,"pasos":[{"slug":"tronco-3.s5.p1","orden":1,"grupo":"tronco-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El sermón no convence","cuerpo":["Cuando alguien se siente juzgado, se defiende: busca argumentos en contra, se enoja o se cierra. Por eso los sermones (\"no puedo creer que sigas usando…\") suelen lograr lo contrario de lo que buscan.","Lo que funciona mejor es escuchar primero, partir de lo que al otro le importa (su salud, su bolsillo, su barrio, sus hijos) y ofrecer algo concreto y fácil de probar."]},"solucion":{}},{"slug":"tronco-3.s5.p2","orden":2,"grupo":"tronco-3.s5.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu tío dice que \"eso del cambio climático es un invento\". ¿Cuál es el mejor primer paso?","opciones":[{"id":"o1","texto":"Preguntarle qué le hace pensar eso y escucharlo antes de responder"},{"id":"o2","texto":"Decirle que está desinformado y que lea más"},{"id":"o3","texto":"Mandarle diez gráficos seguidos al grupo de la familia"},{"id":"o4","texto":"Dejarle de hablar hasta que cambie de idea"}]},"solucion":{"clave":["o1"],"explicacion":"Escuchar primero muestra respeto y te da información sobre qué le preocupa de verdad. Con eso se puede conversar.","por_opcion":{"o3":"Una lluvia de datos suele cerrar la conversación antes de empezarla."}}},{"slug":"tronco-3.s5.p3","orden":3,"grupo":"tronco-3.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Concreto, cercano y con salida","cuerpo":["Los mensajes que más movilizan tienen tres rasgos. Son concretos: una acción puntual en vez de \"salvar el planeta\". Son cercanos: algo del barrio o de la casa, no un glaciar lejano. Y tienen salida: dicen qué se puede hacer, en vez de solo describir el problema.","El miedo solo, sin salida, paraliza. La esperanza con una acción al lado, moviliza."],"lista":["Concreto: \"cerremos la canilla mientras nos lavamos los dientes\"","Cercano: \"el arroyo de acá a la vuelta\"","Con salida: \"si juntamos los reciclables, la cooperativa los retira\""]},"solucion":{}},{"slug":"tronco-3.s5.p4","orden":4,"grupo":"tronco-3.s5.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿El mensaje tiene salida o solo describe el problema?","grupos":[{"id":"g1","nombre":"Tiene una acción concreta"},{"id":"g2","nombre":"Solo describe el problema"}],"items":[{"id":"i1","texto":"Si separamos el aceite usado, lo llevamos al punto de la plaza"},{"id":"i2","texto":"El planeta se está destruyendo"},{"id":"i3","texto":"Probemos ir en bici los viernes"},{"id":"i4","texto":"Ya es demasiado tarde para todo"},{"id":"i5","texto":"Juntemos las pilas en una botella y las llevamos al punto verde"},{"id":"i6","texto":"Los plásticos están en todas partes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Describir el problema no está mal, pero sin una salida deja a la gente angustiada y quieta. Siempre conviene cerrar con qué hacer."}},{"slug":"tronco-3.s5.p5","orden":5,"grupo":"tronco-3.s5.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una conversación sobre ambiente tenga más chances de sumar a alguien? Marcá todas.","opciones":[{"id":"o1","texto":"Partir de algo que al otro le importa"},{"id":"o2","texto":"Proponer una acción chica que puedan hacer juntos"},{"id":"o3","texto":"Reconocer que vos tampoco hacés todo perfecto"},{"id":"o4","texto":"Remarcar todo lo que el otro hace mal"},{"id":"o5","texto":"Usar datos alarmantes sin ninguna propuesta"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Valores compartidos, acción conjunta y humildad. Nadie hace todo bien, y decirlo baja las defensas."}},{"slug":"tronco-3.s5.p6","orden":6,"grupo":"tronco-3.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Asustar mucho a la gente con datos catastróficos es la forma más efectiva de que actúe.","razones":[{"id":"r1","texto":"Porque el miedo sin salida suele llevar a negar o paralizarse"},{"id":"r2","texto":"Porque los datos no importan en ningún caso"},{"id":"r3","texto":"Porque nadie reacciona a ningún mensaje"}]},"solucion":{"valor":false,"explicacion":"El miedo sin una acción posible tiende a generar negación o parálisis. La investigación en comunicación ambiental muestra que funciona mejor combinar la preocupación con acciones concretas y eficaces.","clave":["r1"]}},{"slug":"tronco-3.s5.p7","orden":7,"grupo":"tronco-3.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Datos con cuidado","cuerpo":["Un dato bien usado ayuda muchísimo; uno mal usado destruye la confianza. Antes de compartir un número, conviene aplicarle lo que aprendiste en la unidad anterior: ¿qué unidad tiene?, ¿es total o por persona?, ¿de dónde sale?","Y si alguien te corrige con razón, reconocerlo te hace más creíble, no menos. Nadie sabe todo, y el tema cambia a medida que la ciencia mide mejor."]},"solucion":{}},{"slug":"tronco-3.s5.p8","orden":8,"grupo":"tronco-3.s5.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un compañero prepara un posteo para la escuela. Marcá lo que conviene cambiar.","segmentos":[{"id":"s1","texto":"En nuestra escuela tiramos unas 10 bolsas de basura por día."},{"id":"s2","texto":"Somos todos unos irresponsables y el planeta no tiene arreglo."},{"id":"s3","texto":"La mitad es papel que se podría reciclar."},{"id":"s4","texto":"Si ponemos un tacho para papel en cada aula, la cooperativa lo retira los viernes."}]},"solucion":{"clave":["s2"],"explicacion":"El resto del posteo es concreto, cercano y con salida. Solo la frase de culpa lo arruina.","por_opcion":{"s2":"Culpa y desesperanza: cierra la conversación en vez de abrirla."}}},{"slug":"tronco-3.s5.p9","orden":9,"grupo":"tronco-3.s5.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená una buena conversación sobre un cambio en casa.","items":[{"id":"i1","texto":"Escuchar qué piensa la otra persona"},{"id":"i2","texto":"Encontrar algo que a los dos les importe"},{"id":"i3","texto":"Proponer una prueba chica y concreta"},{"id":"i4","texto":"Acordar cuándo ver cómo salió"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Escuchar, conectar, proponer y revisar. Es una conversación, no un discurso."}},{"slug":"tronco-3.s5.p10","orden":10,"grupo":"tronco-3.s5.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Querés que en tu casa usen menos aire acondicionado. Tu mamá se preocupa mucho por la cuenta de luz. ¿Qué argumento conviene usar primero?","opciones":[{"id":"o1","texto":"Cuánto baja la factura con el aire a 24 °C"},{"id":"o2","texto":"Que el aire acondicionado destruye la capa de ozono"},{"id":"o3","texto":"Que los osos polares se están quedando sin hielo"},{"id":"o4","texto":"Que si no lo hace es mala persona"}]},"solucion":{"clave":["o1"],"explicacion":"Partir de lo que al otro le importa (acá, la cuenta) abre la puerta. El beneficio ambiental viene incluido.","por_opcion":{"o3":"Puede importarle, pero el caso dice qué le preocupa más: la cuenta."}}},{"slug":"tronco-3.s5.p11","orden":11,"grupo":"tronco-3.s5.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá el consejo.","texto":"Un buen mensaje ambiental es {{0}}, {{1}} y tiene una {{2}} clara.","banco":[{"id":"w1","texto":"concreto"},{"id":"w2","texto":"cercano"},{"id":"w3","texto":"salida"},{"id":"w4","texto":"alarmante"},{"id":"w5","texto":"lejano"},{"id":"w6","texto":"culpable"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres palabras que podés usar como filtro antes de hablar o de publicar algo."}},{"slug":"tronco-3.s5.p12","orden":12,"grupo":"tronco-3.s5.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas respuestas a \"reciclar no sirve para nada\" según qué tan probable es que abran la conversación, de más a menos.","items":[{"id":"i1","texto":"\"¿Qué te hizo pensar eso? Yo también tengo dudas con algunas cosas.\""},{"id":"i2","texto":"\"En el barrio la cooperativa retira el papel: ¿te paso el día?\""},{"id":"i3","texto":"\"Hay un estudio que dice lo contrario, te lo mando.\""},{"id":"i4","texto":"\"Con gente como vos no se puede.\""}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Escuchar y ofrecer algo concreto abren; el dato solo informa y el juicio cierra. No hay una fórmula perfecta, pero sí respuestas que casi siempre funcionan peor.","valores":{"i1":"escucha y comparte dudas","i2":"concreta, con salida","i3":"dato sin conexión","i4":"cierra la conversación"}}}]},{"slug":"tronco-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: del saber al hacer","bajada_es":"Hábitos, impacto y comunicación, todo mezclado.","minutos":8,"pasos":[{"slug":"tronco-3.s6.p1","orden":1,"grupo":"tronco-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Del saber al hacer». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"tronco-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el plan de 30 días de Sofi","bajada_es":"Diseñá con Sofi un plan que dure. Aprobalo para completar el tronco.","minutos":10,"pasos":[{"slug":"tronco-3.s7.p1","orden":1,"grupo":"tronco-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["Sofi tiene 16 años, vive con su papá y su hermano en un departamento, y quiere \"hacer algo por el ambiente\". Anotó cómo es su vida: va a la escuela en auto con su papá aunque queda a 12 cuadras, se ducha unos 15 minutos, en casa no separan residuos porque \"no hay lugar\", y el grupo de la familia es un campo de batalla cada vez que habla de estos temas.","Quiere armar un plan de 30 días. Con todo lo que aprendiste en el tronco, vas a ayudarla a elegir, diseñar y sostenerlo."]},"solucion":{}},{"slug":"tronco-3.s7.p2","orden":2,"grupo":"tronco-3.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"De lo que describe Sofi, ¿qué cambio tiene el mejor equilibrio entre impacto y esfuerzo para empezar?","opciones":[{"id":"o1","texto":"Ir caminando o en bici a la escuela, que queda a 12 cuadras"},{"id":"o2","texto":"Comprar un cepillo de dientes de bambú"},{"id":"o3","texto":"Convencer a toda la familia de dejar de comer carne este mes"},{"id":"o4","texto":"Desenchufar el cargador del celular"}],"contexto":"Sofi, 16 años: va a la escuela en auto a 12 cuadras, se ducha 15 minutos, en casa no separan residuos \"porque no hay lugar\", y en el grupo de la familia se discute mucho de ambiente."},"solucion":{"clave":["o1"],"explicacion":"El transporte suele ser de lo que más pesa, y 12 cuadras se hacen caminando. Es alto impacto con esfuerzo razonable.","por_opcion":{"o3":"Puede tener impacto, pero es un esfuerzo grande y depende de otros: difícil para empezar."}}},{"slug":"tronco-3.s7.p3","orden":3,"grupo":"tronco-3.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Para la ducha, ¿cuál es el plan con más chances de convertirse en hábito?","opciones":[{"id":"o1","texto":"Poner una canción de 5 minutos al entrar a la ducha y salir cuando termina"},{"id":"o2","texto":"Proponerse \"ducharse menos\" sin ninguna ayuda"},{"id":"o3","texto":"Anotar en un cuaderno lo mal que se siente cada vez que se pasa"},{"id":"o4","texto":"Ducharse en 2 minutos desde mañana"}],"contexto":"Sofi se ducha unos 15 minutos por día y quiere bajarlo."},"solucion":{"clave":["o1"],"explicacion":"Disparador (entrar a la ducha), rutina (salir con la canción) y una meta alcanzable. Dos minutos es tan exigente que probablemente se abandone.","por_opcion":{"o3":"La culpa desgasta y no ayuda a sostener el hábito."}}},{"slug":"tronco-3.s7.p4","orden":4,"grupo":"tronco-3.s7.p4","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Para los residuos, \"no hay lugar\" es la barrera. ¿Qué ideas atacan esa barrera y cuáles no?","grupos":[{"id":"g1","nombre":"Atacan la barrera"},{"id":"g2","nombre":"No atacan la barrera"}],"items":[{"id":"i1","texto":"Una bolsa colgada en la puerta de la alacena para los reciclables"},{"id":"i2","texto":"Leer más sobre la importancia de reciclar"},{"id":"i3","texto":"Un tacho chico y alto que entre al lado de la heladera"},{"id":"i4","texto":"Esperar a mudarse a una casa más grande"},{"id":"i5","texto":"Sacar los reciclables una vez por semana para que no se acumulen"}],"contexto":"En casa de Sofi no separan residuos porque dicen que no hay lugar en la cocina."},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Si la barrera es de espacio, la solución es de espacio. Información o esperar no cambian el problema."}},{"slug":"tronco-3.s7.p5","orden":5,"grupo":"tronco-3.s7.p5","tipo":"cadena","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el orden en que Sofi debería lanzar su plan de 30 días.","items":[{"id":"i1","texto":"Elegir un solo cambio grande y uno chico para empezar"},{"id":"i2","texto":"Pegar cada cambio a algo que ya hace todos los días"},{"id":"i3","texto":"Preparar el entorno para que sea fácil"},{"id":"i4","texto":"Registrar cada día y revisar a las dos semanas"},{"id":"i5","texto":"Anunciar en el grupo familiar que desde ahora todos tienen que cambiar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Pocos cambios, bien diseñados, con registro. El anuncio para todos es el tipo de sermón que suele terminar en pelea."}},{"slug":"tronco-3.s7.p6","orden":6,"grupo":"tronco-3.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En el grupo de la familia, su papá escribe: \"Eso de caminar a la escuela es una pavada, no cambia nada\". ¿Qué respuesta de Sofi tiene más chances de funcionar?","opciones":[{"id":"o1","texto":"\"Me hace bien caminar y te ahorro el viaje. ¿Probamos dos semanas?\""},{"id":"o2","texto":"\"Sos parte del problema, así no se puede hablar con vos, papá.\""},{"id":"o3","texto":"\"Te mando este informe del IPCC de 3.000 páginas para que leas.\""},{"id":"o4","texto":"\"Bueno, entonces sigo yendo en auto y no digo nada más.\""}],"contexto":"El grupo de WhatsApp de la familia de Sofi suele terminar en discusión cuando habla de ambiente."},"solucion":{"clave":["o1"],"explicacion":"Parte de lo que le importa al otro (comodidad, salud), no lo juzga y propone una prueba chica con fecha para revisar.","por_opcion":{"o3":"Mucha información de golpe suele cerrar la conversación."}}},{"slug":"tronco-3.s7.p7","orden":7,"grupo":"tronco-3.s7.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si a los 10 días Sofi falla dos veces con la ducha corta, lo mejor es abandonar el plan porque ya no va a formar el hábito.","razones":[{"id":"r1","texto":"Porque lo que cuenta es volver, no la perfección"},{"id":"r2","texto":"Porque los hábitos se rompen para siempre con un error"},{"id":"r3","texto":"Porque la ducha no es un hábito"}]},"solucion":{"valor":false,"explicacion":"Saltearse días no arruina el hábito: lo que cuenta es volver. En el estudio de Lally, la formación de hábitos no se vio afectada de forma importante por faltar un día.","clave":["r1"]}},{"slug":"tronco-3.s7.p8","orden":8,"grupo":"tronco-3.s7.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la ducha de Sofi usa 10 litros por minuto y baja de 15 a 5 minutos, ¿cuántos litros ahorra en los 30 días del plan?","unidad":"litros","decimales":0},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"Ahorra 10 minutos por día × 10 litros por minuto = 100 litros por día. × 30 días = 3.000 litros."}},{"slug":"tronco-3.s7.p8.v2","orden":8,"grupo":"tronco-3.s7.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la ducha de Sofi usa 10 litros por minuto y baja de 12 a 5 minutos, ¿cuántos litros ahorra en los 30 días del plan?","unidad":"litros","decimales":0},"solucion":{"valor":2100,"tolerancia":42,"explicacion":"Ahorra 7 minutos por día × 10 litros por minuto = 70 litros por día. × 30 días = 2.100 litros."}},{"slug":"tronco-3.s7.p8.v3","orden":8,"grupo":"tronco-3.s7.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la ducha de Sofi usa 10 litros por minuto y baja de 18 a 5 minutos, ¿cuántos litros ahorra en los 30 días del plan?","unidad":"litros","decimales":0},"solucion":{"valor":3900,"tolerancia":78,"explicacion":"Ahorra 13 minutos por día × 10 litros por minuto = 130 litros por día. × 30 días = 3.900 litros."}},{"slug":"tronco-3.s7.p9","orden":9,"grupo":"tronco-3.s7.p9","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"A los 30 días, ¿qué conviene que haga Sofi? Marcá todo lo que ayuda.","opciones":[{"id":"o1","texto":"Revisar qué funcionó y qué no, sin juzgarse"},{"id":"o2","texto":"Mantener lo que ya sale solo y sumar un solo cambio nuevo"},{"id":"o3","texto":"Contar en casa los resultados concretos, como los litros ahorrados"},{"id":"o4","texto":"Empezar diez cambios nuevos a la vez para recuperar el tiempo"},{"id":"o5","texto":"Dejar todo porque ya pasó el mes"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Revisar, sostener lo que ya es hábito, sumar de a uno y mostrar resultados concretos: así el plan se vuelve una forma de vivir."}},{"slug":"tronco-3.s7.p10","orden":10,"grupo":"tronco-3.s7.p10","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Sofi escribe su reflexión final. Marcá lo que contradice lo que aprendiste.","segmentos":[{"id":"s1","texto":"Lo más importante que cambié fue ir caminando a la escuela."},{"id":"s2","texto":"Como la ducha me cuesta, voy a dejarla: si no lo hago perfecto, no vale."},{"id":"s3","texto":"Mi papá empezó a ir caminando al trabajo los viernes."},{"id":"s4","texto":"Igual lo que yo hago no cambia nada, lo importante lo tienen que hacer otros."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Perfeccionismo e impotencia son las dos trampas que más hacen abandonar. Su propia historia muestra lo contrario.","por_opcion":{"s2":"Perfección no hace falta: una ducha de 8 minutos ya ahorra mucho respecto de 15.","s4":"Su propio caso lo desmiente: su cambio contagió a su papá."}}}]}]}$ac$::jsonb);
